async function takeGroupSnapshot(groupId, snapshotType = 'auto') {
    try {
        const groupRes = await pool.query('SELECT * FROM family_groups WHERE id=$1', [groupId]);
        const group = groupRes.rows[0];
        if (!group) return null;

        // כל שאר השאילתות — כישלון שקט אם טבלה/עמודה לא קיימת
        const safe = q => pool.query(q, [groupId]).catch(() => ({ rows: [] }));
        const [
            usersRes, storeSettingsRes, catalogRes, ordersRes,
            calSettingsRes, calServicesRes, calEventsRes,
            practitionersRes, resourcesRes, apptRes, clientRecordsRes,
            inventoryRes, commissionsRes, rfqRes
        ] = await Promise.all([
            pool.query('SELECT id,nickname,email,phone,role,status,balance,birth_year,id_number FROM users WHERE group_id=$1', [groupId]).catch(()=>({rows:[]})),
            safe('SELECT * FROM store_settings WHERE group_id=$1'),
            safe('SELECT * FROM store_catalog WHERE group_id=$1'),
            pool.query(`SELECT * FROM store_orders WHERE group_id=$1 AND created_at > NOW() - INTERVAL '30 days'`, [groupId]).catch(()=>({rows:[]})),
            safe('SELECT * FROM calendar_settings WHERE group_id=$1'),
            safe('SELECT * FROM calendar_services WHERE group_id=$1'),
            pool.query(`SELECT * FROM calendar_events WHERE group_id=$1 AND event_date >= CURRENT_DATE - 30`, [groupId]).catch(()=>({rows:[]})),
            pool.query('SELECT * FROM beauty_practitioners WHERE business_group_id=$1', [groupId]).catch(()=>({rows:[]})),
            pool.query('SELECT * FROM beauty_resources WHERE business_group_id=$1', [groupId]).catch(()=>({rows:[]})),
            pool.query(`SELECT * FROM beauty_appointments WHERE business_group_id=$1 AND created_at > NOW() - INTERVAL '30 days'`, [groupId]).catch(()=>({rows:[]})),
            pool.query('SELECT * FROM beauty_client_records WHERE business_group_id=$1', [groupId]).catch(()=>({rows:[]})),
            pool.query('SELECT * FROM beauty_inventory WHERE business_group_id=$1', [groupId]).catch(()=>({rows:[]})),
            pool.query(`SELECT * FROM beauty_commissions WHERE business_group_id=$1 AND status='unpaid'`, [groupId]).catch(()=>({rows:[]})),
            pool.query(`SELECT * FROM beauty_rfq WHERE business_group_id=$1 AND created_at > NOW() - INTERVAL '30 days'`, [groupId]).catch(()=>({rows:[]})),
        ]);

        const snapshotData = {
            v: 1, group,
            users:                usersRes.rows,
            store_settings:       storeSettingsRes.rows[0] || null,
            catalog:              catalogRes.rows,
            orders:               ordersRes.rows,
            calendar_settings:    calSettingsRes.rows[0] || null,
            calendar_services:    calServicesRes.rows,
            calendar_events:      calEventsRes.rows,
            beauty_practitioners: practitionersRes.rows,
            beauty_resources:     resourcesRes.rows,
            beauty_appointments:  apptRes.rows,
            beauty_client_records: clientRecordsRes.rows,
            beauty_inventory:     inventoryRes.rows,
            beauty_commissions:   commissionsRes.rows,
            beauty_rfq:           rfqRes.rows,
        };

        // INSERT — ללא עמודות שעשויות להיות חסרות (created_at מוגדר DEFAULT)
        await pool.query(
            `INSERT INTO group_snapshots (group_id, snapshot_type, snapshot_data)
             VALUES ($1,$2,$3)`,
            [groupId, snapshotType, JSON.stringify(snapshotData)]
        );

        // ניקוי snapshot ישנים — בלוק נפרד כדי שכישלון לא יבטל את ה-INSERT
        pool.query(
            `DELETE FROM group_snapshots WHERE group_id=$1 AND snapshot_type='auto'
             AND id NOT IN (
               SELECT id FROM group_snapshots WHERE group_id=$1 AND snapshot_type='auto'
               ORDER BY id DESC LIMIT 30
             )`,
            [groupId]
        ).catch(e => console.warn('[SNAPSHOT CLEANUP]', e.message));

        return true;
    } catch(e) { console.error('[SNAPSHOT]', e.message); return { error: e.message }; }
}

// Daily auto-snapshot — רץ כל 24 שעות
async function runDailySnapshots() {
    try {
        const groups = await pool.query(`SELECT id FROM family_groups WHERE is_deleted=false OR is_deleted IS NULL`);
        console.log(`[SNAPSHOT] Starting daily snapshots for ${groups.rows.length} groups`);
        for (const g of groups.rows) {
            // דלג אם כבר יש snapshot של היום
            const todayCheck = await pool.query(
                `SELECT id FROM group_snapshots WHERE group_id=$1 AND snapshot_type='auto' AND created_at > NOW() - INTERVAL '20 hours' LIMIT 1`,
                [g.id]
            ).catch(() => ({ rows: [] }));
            if (todayCheck.rows.length > 0) continue;
            await takeGroupSnapshot(g.id, 'auto');
            await new Promise(r => setTimeout(r, 3000)); // throttle — reduce memory pressure
        }
        // מחיקת snapshots שפגו תוקף (גוארד אם expires_at עדיין לא קיים)
        await pool.query(`DELETE FROM group_snapshots WHERE expires_at IS NOT NULL AND expires_at < NOW()`).catch(()=>{});
        console.log(`[SNAPSHOT] Daily snapshots done`);
    } catch(e) { console.error('[SNAPSHOT DAILY]', e.message); }
}
// תזמון snapshot יומי ב-00:00 בדיוק (חצות)
function scheduleNextMidnightSnapshot() {
    const now = new Date();
    const next = new Date(now);
    next.setHours(24, 0, 30, 0); // חצות הלילה הבא + 30 שניות buffer
    const msUntilMidnight = next.getTime() - now.getTime();
    setTimeout(() => {
        runDailySnapshots();
        scheduleNextMidnightSnapshot(); // מתזמן מחדש ל-חצות הבא
    }, msUntilMidnight);
    const h = Math.floor(msUntilMidnight / 3600000);
    const m = Math.floor((msUntilMidnight % 3600000) / 60000);
    console.log(`[SNAPSHOT] Next auto-snapshot scheduled in ${h}h ${m}m (at midnight)`);
}
scheduleNextMidnightSnapshot();

// ===== Auto-dispatch משימות חוזרות (כל 5 דקות) =====
async function dispatchRecurringTasks() {
    try {
        const dayNames = ['ראשון','שני','שלישי','רביעי','חמישי','שישי','שבת'];
        const now = new Date();
        const todayName = dayNames[now.getDay()];
        const hourNow = now.getHours();
        // שעת פרסום: 08:00 בלבד
        if (hourNow < 8) return;
        const rTasks = await pool.query(`SELECT * FROM tasks WHERE is_recurring=TRUE AND status='pending'`);
        for (const t of rTasks.rows) {
            if (!t.recurring_days || !t.recurring_days.includes(todayName)) continue;
            // בדוק אם כבר פורסמה היום
            const existing = await pool.query(
                `SELECT id FROM tasks WHERE group_id=$1 AND title=$2 AND assigned_to=$3 AND is_recurring=FALSE AND created_at::date=CURRENT_DATE`,
                [t.group_id, t.title, t.assigned_to]
            );
            if (existing.rows.length > 0) continue;
            // פרסם עותק חד-פעמי עם deadline מחר
            const deadline = new Date(now); deadline.setDate(deadline.getDate() + 1);
            await pool.query(
                `INSERT INTO tasks (group_id, title, reward, assigned_to, deadline, status, require_ai_check, is_recurring, recurring_days, created_by, priority) VALUES ($1,$2,$3,$4,$5,'pending',$6,FALSE,'',$7,$8)`,
                [t.group_id, t.title, t.reward, t.assigned_to, deadline, t.require_ai_check, t.created_by, t.priority || 'medium']
            );
        }
    } catch(e) { console.error('[RECURRING] error:', e.message); }
}
setInterval(dispatchRecurringTasks, 5 * 60 * 1000); // כל 5 דקות
setTimeout(dispatchRecurringTasks, 90000); // דחייה 90 שניות מסטארטאפ

// ===== ניקוי חודשי של תמונות הוכחה מ-Cloudinary (ה-1 לחודש) =====
async function monthlyCloudinaryCleanup() {
    try {
        const settingsRes = await pool.query(`SELECT key, value FROM system_settings WHERE key IN ('cloudinary_cloud_name', 'cloudinary_api_secret')`);
        const settings = Object.fromEntries(settingsRes.rows.map(r => [r.key, r.value]));
        const cloudName = settings['cloudinary_cloud_name'];
        const apiSecret = settings['cloudinary_api_secret'];
        if (!cloudName || !apiSecret) return;
        // מצא משימות עם תמונות מחודש שעבר
        const startOfMonth = new Date(); startOfMonth.setDate(1); startOfMonth.setHours(0,0,0,0);
        const oldTasks = await pool.query(
            `SELECT id, proof_image_url FROM tasks WHERE proof_image_url IS NOT NULL AND updated_at < $1`,
            [startOfMonth]
        );
        for (const row of oldTasks.rows) {
            try {
                const url = row.proof_image_url;
                // חלץ public_id מה-URL
                const match = url.match(/\/upload\/(?:v\d+\/)?(.+)\.[^.]+$/);
                if (!match) continue;
                const publicId = match[1];
                // Cloudinary delete API
                const timestamp = Math.floor(Date.now() / 1000);
                const crypto = require('crypto');
                const sig = crypto.createHash('sha1').update(`public_id=${publicId}&timestamp=${timestamp}${apiSecret}`).digest('hex');
                await fetch(`https://api.cloudinary.com/v1_1/${cloudName}/image/destroy`, {
                    method: 'POST',
                    headers: { 'Content-Type': 'application/json' },
                    body: JSON.stringify({ public_id: publicId, timestamp, signature: sig, api_key: '' })
                });
                await pool.query('UPDATE tasks SET proof_image_url=NULL WHERE id=$1', [row.id]);
            } catch(e2) { console.error('[CLOUDINARY_CLEANUP]', e2.message); }
        }
        console.log(`[CLOUDINARY_CLEANUP] processed ${oldTasks.rows.length} tasks`);
    } catch(e) { console.error('[CLOUDINARY_CLEANUP] error:', e.message); }
}
// הפעל ב-1 לחודש — פיצול לחלקים כדי לא לחרוג מ-INT32_MAX (2147483647ms ≈ 24.8 יום)
function scheduleMonthlyCleanup() {
    const now = new Date();
    const next = new Date(now.getFullYear(), now.getMonth() + 1, 1, 3, 0, 0);
    let ms = next.getTime() - now.getTime();
    const MAX_SAFE = 20 * 24 * 60 * 60 * 1000; // 20 יום — תמיד מתחת ל-INT32_MAX
    if (ms > MAX_SAFE) {
        setTimeout(() => scheduleMonthlyCleanup(), MAX_SAFE);
        return;
    }
    setTimeout(() => { monthlyCloudinaryCleanup(); scheduleMonthlyCleanup(); }, ms);
}
scheduleMonthlyCleanup();


