app.post('/api/biz/register', async (req, res) => {
    try {
        const { phone, verified_token, password, business_name } = req.body;
        if (!phone || !verified_token || !password || !business_name) {
            return res.status(400).json({ success: false, error: 'פרמטרים חסרים' });
        }
        if (password.length < 6) {
            return res.status(400).json({ success: false, error: 'סיסמה חייבת להכיל לפחות 6 תווים' });
        }

        // אימות verified_token — DELETE אטומי למניעת race condition
        const vtHash = _bizHashOtp(verified_token);
        const vtRes = await pool.query(
            `DELETE FROM business_otp
             WHERE phone=$1 AND purpose='verified' AND code_hash=$2 AND expires_at > NOW()
             RETURNING id`,
            [phone, vtHash]
        );
        if (vtRes.rowCount === 0) {
            return res.status(400).json({ success: false, error: 'אימות הטלפון פג תוקף. יש להתחיל מחדש.' });
        }

        // בדיקת כפילות — phone קיים בכל תפקיד? (מספר dev מוחרג)
        const DEV_PHONE = '0526626619';
        if (phone !== DEV_PHONE) {
            const dupRes = await pool.query(`SELECT id FROM users WHERE phone=$1`, [phone]);
            if (dupRes.rows.length > 0) {
                return res.status(400).json({ success: false, error: 'מספר טלפון זה כבר רשום במערכת. נסה להתחבר או פנה לתמיכה.' });
            }
        }

        const passwordHash = await bcrypt.hash(password, 10);

        // INSERT family_groups
        const gRes = await pool.query(
            `INSERT INTO family_groups (name, type, member_type, business_type, wizard_completed, is_onboarded, group_code)
             VALUES ($1, 'BUSINESS', 'biz', 'other', FALSE, TRUE, $2)
             RETURNING id`,
            [business_name, 'B' + _bizCrypto.randomBytes(4).toString('hex').toUpperCase().slice(0, 7)]
        );
        const groupId = gRes.rows[0].id;

        // INSERT users (admin)
        const uRes = await pool.query(
            `INSERT INTO users (group_id, nickname, role, phone, password_hash, status)
             VALUES ($1, $2, 'ADMIN', $3, $4, 'active')
             RETURNING id`,
            [groupId, business_name, phone, passwordHash]
        );
        const userId = uRes.rows[0].id;

        const deviceHint = req.headers['user-agent']?.slice(0, 100) || null;
        const token = await createFamilySession(groupId, userId, deviceHint, 'biz');

        res.json({ success: true, token, group_id: groupId, user_id: userId, business_name, wizard_completed: false });
    } catch(e) {
        console.error('biz register error:', e.message);
        console.error('biz register stack:', e.stack);
        res.status(500).json({ success: false, error: 'שגיאה ביצירת החשבון' });
    }
});

app.post('/api/biz/login', async (req, res) => {
    try {
        const { phone, password } = req.body;
        if (!phone || !password) {
            return res.status(400).json({ success: false, error: 'טלפון וסיסמה נדרשים' });
        }

        const uRes = await pool.query(
            `SELECT u.id, u.group_id, u.password_hash, fg.wizard_completed, fg.name AS business_name
             FROM users u
             JOIN family_groups fg ON fg.id = u.group_id
             WHERE u.phone=$1 AND fg.member_type='biz' AND u.role='ADMIN' AND u.status='active'`,
            [phone]
        );
        if (uRes.rows.length === 0) {
            return res.status(400).json({ success: false, error: 'מספר טלפון או סיסמה שגויים' });
        }

        const user = uRes.rows[0];
        const passOk = await bcrypt.compare(password, user.password_hash);
        if (!passOk) {
            return res.status(400).json({ success: false, error: 'מספר טלפון או סיסמה שגויים' });
        }

        const deviceHint = req.headers['user-agent']?.slice(0, 100) || null;
        const token = await createFamilySession(user.group_id, user.id, deviceHint, 'biz');

        res.json({ success: true, token, group_id: user.group_id, user_id: user.id, wizard_completed: user.wizard_completed, business_name: user.business_name });
    } catch(e) {
        console.error('biz login error:', e);
        res.status(500).json({ success: false, error: 'שגיאה בהתחברות' });
    }
});

app.get('/api/biz/me', verifyBiz, async (req, res) => {
    try {
        const { groupId, userId } = req.bizAuth;

        const [gRes, filledRes, uRes] = await Promise.all([
            pool.query(`SELECT * FROM family_groups WHERE id=$1`, [groupId]),
            pool.query(
                `SELECT employee_role_type, COUNT(*)::int AS cnt
                 FROM users
                 WHERE group_id=$1 AND status='active' AND employee_role_type IS NOT NULL
                 GROUP BY employee_role_type`,
                [groupId]
            ),
            userId
                ? pool.query(`SELECT first_name, last_name, birth_year FROM users WHERE id=$1`, [userId])
                : Promise.resolve({ rows: [] })
        ]);

        if (!gRes.rows[0]) return res.status(404).json({ success: false, error: 'עסק לא נמצא' });

        const filled_by_role = {};
        for (const r of filledRes.rows) filled_by_role[r.employee_role_type] = r.cnt;

        const adminUser = uRes.rows[0] || {};
        res.json({ success: true, ...gRes.rows[0], filled_by_role,
            first_name: adminUser.first_name || null,
            last_name:  adminUser.last_name  || null,
            birth_year: adminUser.birth_year || null,
        });
    } catch(e) {
        console.error('biz me error:', e);
        res.status(500).json({ success: false, error: 'שגיאה בטעינת נתוני העסק' });
    }
});

app.patch('/api/biz/wizard/complete', verifyBiz, async (req, res) => {
    try {
        const { groupId, userId } = req.bizAuth;
        const {
            business_type, managed_modules, staff_roles,
            admin_email, first_name, last_name, city, birth_year,
            terms_accepted,
            street_address, opening_hours
        } = req.body;

        if (!business_type || !Array.isArray(managed_modules) || !Array.isArray(staff_roles)) {
            return res.status(400).json({ success: false, error: 'פרמטרים חסרים' });
        }
        if (terms_accepted !== true) {
            return res.status(400).json({ success: false, error: 'יש לאשר את התקנון' });
        }
        if (!admin_email || !first_name || !last_name || !city || !birth_year) {
            return res.status(400).json({ success: false, error: 'פרטי חשבון חסרים' });
        }
        const yr = parseInt(birth_year, 10);
        if (isNaN(yr) || yr < 1940 || yr > 2010) {
            return res.status(400).json({ success: false, error: 'שנת לידה לא תקינה (1940–2010)' });
        }

        await pool.query(
            `UPDATE family_groups
             SET business_type=$1, managed_modules=$2, staff_roles=$3, wizard_completed=TRUE,
                 admin_email=$4, city=$5, terms_accepted_at=NOW(),
                 street_address=$6, opening_hours=$7
             WHERE id=$8`,
            [
                business_type,
                JSON.stringify(managed_modules),
                JSON.stringify(staff_roles),
                admin_email.toLowerCase().trim(),
                city.trim(),
                street_address || null,
                opening_hours ? JSON.stringify(opening_hours) : null,
                groupId
            ]
        );

        if (userId) {
            await pool.query(
                `UPDATE users SET first_name=$1, last_name=$2, birth_year=$3 WHERE id=$4`,
                [first_name.trim(), last_name.trim(), yr, userId]
            );
        }

        res.json({ success: true });
    } catch(e) {
        console.error('biz wizard/complete error:', e.message);
        res.status(500).json({ success: false, error: 'שגיאה בשמירת הוויזארד' });
    }
});

