app.get('/api/data/:userId', async (req, res) => {
    const _t0 = Date.now();
    try {
        const userRes = await pool.query('SELECT * FROM users WHERE id = $1', [req.params.userId]);
        if (userRes.rows.length === 0) return res.status(404).json({ error: 'User not found' });
        const user = userRes.rows[0];

        // עדכון last_seen + מכסת AI יומית (fire-and-forget — לא מחכים)
        pool.query('UPDATE users SET last_seen=NOW() WHERE id=$1', [user.id]).catch(()=>{});
        pool.query(`UPDATE family_groups SET ai_tokens = 10, last_token_reset = CURRENT_DATE WHERE id = $1 AND (last_token_reset IS NULL OR last_token_reset < CURRENT_DATE)`, [user.group_id]).catch(()=>{});

        const groupRes = await pool.query('SELECT * FROM family_groups WHERE id = $1', [user.group_id]);
        const group = groupRes.rows[0];

        // Parallel fetch of all independent data (including admin balance)
        const [adminBalRes, tasks, pantry, shoppingList, goals, allBundles, userBundles, gameAssignments] = await Promise.all([
            pool.query("SELECT COALESCE(SUM(CASE WHEN type = 'income' THEN amount ELSE -amount END), 0) as total FROM transactions t JOIN users u ON t.user_id = u.id WHERE t.group_id = $1 AND u.role = 'ADMIN'", [group.id]),
            pool.query(`SELECT t.*, u.nickname as assignee_name FROM tasks t LEFT JOIN users u ON t.assigned_to = u.id WHERE t.group_id = $1 ORDER BY CASE WHEN t.priority='high' THEN 1 WHEN t.priority='low' THEN 3 ELSE 2 END, t.created_at DESC LIMIT 200`, [group.id]),
            pool.query('SELECT * FROM pantry WHERE group_id = $1 ORDER BY updated_at DESC', [group.id]),
            pool.query('SELECT sl.*, u.nickname as requester_name FROM shopping_list sl LEFT JOIN users u ON sl.requester_id = u.id WHERE sl.group_id = $1 ORDER BY sl.added_at DESC', [group.id]),
            pool.query('SELECT g.*, u.nickname as owner_name FROM goals g LEFT JOIN users u ON g.target_user_id = u.id WHERE g.user_id = $1 OR g.target_user_id = $1', [user.id]),
            pool.query(`SELECT id, title, type, age_group, threshold, reward, created_by FROM quiz_bundles WHERE created_by = $1 OR created_by = 'SYSTEM' ORDER BY created_at DESC LIMIT 50`, [String(user.group_id)]),
            pool.query(`SELECT ua.*, qb.title, qb.type, qb.age_group, qb.threshold, qb.text_content, qb.reward as default_reward, u.nickname as assignee_name FROM user_assignments ua JOIN quiz_bundles qb ON ua.bundle_id = qb.id LEFT JOIN users u ON ua.user_id = u.id WHERE ua.user_id = $1 OR $2 = 'ADMIN'`, [user.id, user.role]),
            user.role === 'ADMIN'
              ? pool.query(`SELECT ga.*, g.title, g.subject, g.thumbnail_emoji, g.file_path, g.difficulty, (ga.rounds_total - COALESCE(ga.rounds_used,0)) as rounds_left, u.nickname as child_name FROM game_assignments ga JOIN games_catalog g ON g.id = ga.game_id LEFT JOIN users u ON u.id = ga.child_user_id WHERE ga.family_group_id = $1 AND ga.status = 'active' AND (ga.expires_at IS NULL OR ga.expires_at > NOW()) ORDER BY ga.assigned_at DESC`, [group.id])
              : pool.query(`SELECT ga.*, g.title, g.subject, g.thumbnail_emoji, g.file_path, g.difficulty, (ga.rounds_total - COALESCE(ga.rounds_used,0)) as rounds_left FROM game_assignments ga JOIN games_catalog g ON g.id = ga.game_id WHERE ga.child_user_id = $1 AND ga.status = 'active' AND (ga.expires_at IS NULL OR ga.expires_at > NOW()) ORDER BY ga.assigned_at DESC`, [user.id])
        ]);
        group.admin_total_balance = adminBalRes.rows[0].total;

        // Parallel: child balance + weekly spend + community businesses (all independent of the Promise.all above)
        const _startOfWeek = new Date(); _startOfWeek.setDate(_startOfWeek.getDate() - _startOfWeek.getDay());
        const [childBalRes, spentRes, commBizRes] = await Promise.all([
            user.role !== 'ADMIN'
                ? pool.query("SELECT COALESCE(SUM(CASE WHEN type='income' THEN amount ELSE -amount END),0) as total FROM transactions WHERE user_id=$1", [user.id])
                : Promise.resolve(null),
            user.role !== 'ADMIN'
                ? pool.query("SELECT COALESCE(SUM(amount), 0) as spent FROM transactions WHERE user_id = $1 AND type = 'expense' AND date >= $2", [user.id, _startOfWeek])
                : Promise.resolve(null),
            group.community_id
                ? pool.query(`SELECT cb.discount_pct, cb.created_at, b.name as business_name, b.id as business_id, b.group_code,
                               c.name as comm_name, c.id as community_id,
                               COALESCE(ss.logo_url, b.image_url) as logo_url
                        FROM community_businesses cb
                        JOIN family_groups b ON cb.business_id = b.id
                        JOIN communities c ON cb.community_id = c.id
                        LEFT JOIN store_settings ss ON ss.group_id = b.id
                        WHERE cb.community_id = $1 AND cb.status = 'approved'`, [group.community_id])
                : Promise.resolve(null)
        ]);
        if (childBalRes) user.computed_balance = childBalRes.rows[0].total;
        const weeklyStats = spentRes ? { spent: spentRes.rows[0].spent, limit: user.allowance_amount } : null;
        const community_businesses = commBizRes ? commBizRes.rows : [];
        const community_updates = [];
        if (commBizRes && group.type === 'FAMILY') {
            commBizRes.rows.forEach(biz => {
                community_updates.push({
                    type: 'system', category: 'community', id: `biz_${biz.business_name}`,
                    user_id: 0, user_name: 'קהילה',
                    description: `הטבה חדשה בקהילת ${biz.comm_name}: ${biz.business_name} (הנחה: ${biz.discount_pct}%) 🛍️`,
                    amount: 0, date: biz.created_at ? new Date(biz.created_at) : new Date()
                });
            });
        }

        // Best-price lookup: parallel individual queries (avoids slow DISTINCT ON + full-scan)
        if (shoppingList.rows.length > 0) {
            await Promise.all(shoppingList.rows.map(async (item) => {
                const _norm = item.normalized_name || item.item_name;
                const _words = _norm.split(' ').filter(w => w.length > 2);
                const _kw = _words.length > 0 ? _words[0] : '';
                try {
                    const bp = await pool.query(
                        `SELECT sti.price_per_unit, st.store_name, st.branch_name, st.trip_date, st.group_id
                         FROM shopping_trip_items sti JOIN shopping_trips st ON sti.trip_id = st.id
                         WHERE (sti.item_name = $1 OR sti.normalized_name = $2
                                OR ($3 != '' AND (sti.normalized_name ILIKE $4 OR sti.item_name ILIKE $4)))
                         AND sti.price_per_unit > 0
                         ORDER BY sti.price_per_unit ASC LIMIT 1`,
                        [item.item_name, _norm, _kw, '%' + _kw + '%']
                    );
                    if (bp.rows.length > 0) {
                        const r = bp.rows[0];
                        item.best_price = { price_per_unit: r.price_per_unit, store_name: r.store_name || 'ספק לא ידוע', branch_name: r.branch_name || '', trip_date: r.trip_date, is_local: r.group_id === group.id };
                    }
                } catch(e) {}
            }));
        }

        const _elapsed = Date.now() - _t0;
        if (_elapsed > 500) console.warn(`[PERF] /api/data/${req.params.userId} took ${_elapsed}ms`);
        res.json({
            user, group, tasks: tasks.rows, pantry: pantry.rows, shopping_list: shoppingList.rows,
            goals: goals.rows, quiz_bundles: userBundles.rows, all_bundles: allBundles.rows,
            game_assignments: gameAssignments.rows,
            weekly_stats: weeklyStats, community_updates: community_updates, community_businesses: community_businesses
        });
    } catch (e) {
        console.error('Error in /api/data/:userId:', e);
        res.status(500).json({ error: e.message });
    }
});

