app.put('/api/admin/user-details/:userId', async (req, res) => {
    try {
        const adminUserId = req.body.adminId;
        const targetUserId = req.params.userId;

        const aRes = await pool.query('SELECT group_id, role FROM users WHERE id=$1', [adminUserId]);
        if (!aRes.rows.length || aRes.rows[0].role !== 'ADMIN') return res.status(403).json({ error: 'אין הרשאה' });
        const adminGroupId = aRes.rows[0].group_id;
        const uRes = await pool.query('SELECT group_id FROM users WHERE id=$1 AND group_id=$2', [targetUserId, adminGroupId]);
        if (!uRes.rows.length) return res.status(403).json({ error: 'אין הרשאה' });

        const { nickname, email, phone, password, role } = req.body;
        const sets = []; const vals = [];
        if (nickname && nickname.trim()) { vals.push(nickname.trim()); sets.push(`nickname=$${vals.length}`); }
        if (email !== undefined) { vals.push(email ? email.trim().toLowerCase() : null); sets.push(`email=$${vals.length}`); }
        if (phone !== undefined) { vals.push(phone ? phone.trim() : null); sets.push(`phone=$${vals.length}`); }
        if (password && password.trim().length >= 4) { vals.push(password.trim()); sets.push(`password_hash=$${vals.length}`); }
        if (role && ['ADMIN','CHILD','MEMBER'].includes(role)) { vals.push(role); sets.push(`role=$${vals.length}`); }
        if (sets.length === 0) return res.json({ success: true });
        vals.push(targetUserId);
        await pool.query(`UPDATE users SET ${sets.join(',')} WHERE id=$${vals.length}`, vals);
        res.json({ success: true });
    } catch(e) { res.status(500).json({ error: e.message }); }
});

app.post('/api/users/:id/password', verifyFamily, async (req, res) => {
    try {
        const callerId = req.familyAuth.userId;
        const targetId = parseInt(req.params.id);
        if (callerId !== targetId) return res.status(403).json({ error: 'אין הרשאה לשנות סיסמה של משתמש אחר' });
        const { oldPassword, newPassword } = req.body;
        if (!newPassword || newPassword.length < 4) return res.status(400).json({ error: 'סיסמה חדשה חייבת להכיל לפחות 4 תווים' });
        const u = await pool.query('SELECT password_hash FROM users WHERE id=$1', [targetId]);
        if (!u.rows.length) return res.status(404).json({ error: 'משתמש לא נמצא' });
        const stored = u.rows[0].password_hash || '';
        const oldOk = stored.startsWith('$2')
            ? await bcrypt.compare(oldPassword, stored)
            : oldPassword === stored;
        if (!oldOk) return res.status(401).json({ error: 'סיסמה נוכחית שגויה' });
        await pool.query('UPDATE users SET password_hash=$1 WHERE id=$2', [await bcrypt.hash(newPassword, 10), targetId]);
        res.json({ success: true });
    } catch(e) { res.status(500).json({ error: e.message }); }
});

// First-login password set (for member accounts created by business — no old password required)
app.post('/api/users/:id/set-first-password', async (req, res) => {
    try {
        const { newPassword, id_number, email, birth_year } = req.body;
        if (!newPassword || newPassword.length < 4) return res.status(400).json({ error: 'סיסמה חייבת להכיל לפחות 4 תווים' });
        const u = await pool.query('SELECT must_change_password FROM users WHERE id=$1', [req.params.id]);
        if (!u.rows.length) return res.status(404).json({ error: 'משתמש לא נמצא' });
        if (!u.rows[0].must_change_password) return res.status(403).json({ error: 'לא ניתן לאפס סיסמה בשלב זה' });
        const sets = ['password_hash=$1', 'must_change_password=false'];
        const vals = [await bcrypt.hash(newPassword, 10)];
        if (id_number !== undefined && String(id_number).trim() !== '') { vals.push(String(id_number).trim()); sets.push(`id_number=$${vals.length}`); }
        if (email !== undefined && String(email).trim() !== '') { vals.push(String(email).trim().toLowerCase()); sets.push(`email=$${vals.length}`); }
        const by = parseInt(birth_year);
        if (!isNaN(by) && by >= 1920 && by <= 2020) { vals.push(by); sets.push(`birth_year=$${vals.length}`); }
        vals.push(req.params.id);
        await pool.query(`UPDATE users SET ${sets.join(', ')} WHERE id=$${vals.length}`, vals);
        res.json({ success: true });
    } catch(e) { res.status(500).json({ error: e.message }); }
});

app.post('/api/admin/adjust-balance', verifyFamily, async (req, res) => {
    try {
        // adminId מה-body מתעלמים לחלוטין — משתמשים אך ורק בטוקן
        const adminUserId = req.familyAuth.userId;
        const adminGroupId = req.familyAuth.groupId;

        // שכבה 2: ודא שהמשתמש הוא ADMIN באותה קבוצה
        const adminCheck = await pool.query(
            `SELECT role FROM users WHERE id=$1 AND group_id=$2`,
            [adminUserId, adminGroupId]
        );
        if (!adminCheck.rows.length || adminCheck.rows[0].role !== 'ADMIN') {
            return res.status(403).json({ error: 'נדרשת הרשאת מנהל' });
        }

        const { childId, type, amount, reason } = req.body;

        // שכבה 3: ודא ש-childId שייך לאותה קבוצה
        const childCheck = await pool.query(
            `SELECT id FROM users WHERE id=$1 AND group_id=$2`,
            [childId, adminGroupId]
        );
        if (!childCheck.rows.length) {
            return res.status(404).json({ error: 'ילד לא נמצא בקבוצה' });
        }

        const actAmount = type === 'deduct' ? -(parseFloat(amount)||0) : (parseFloat(amount)||0);
        await pool.query('UPDATE users SET balance = balance + $1 WHERE id=$2', [actAmount, childId]);
        await pool.query(
            `INSERT INTO transactions (user_id, group_id, amount, description, category, type) VALUES ($1, $2, $3, $4, 'other', $5)`,
            [childId, adminGroupId, parseFloat(amount)||0, reason, type === 'deduct' ? 'expense' : 'income']
        );
        // audit log — performed_by_user_id מהטוקן בלבד
        await pool.query(
            `INSERT INTO family_audit_log (action, performed_by_user_id, group_id, target_user_id, amount, extra_type, reason) VALUES ('adjust_balance', $1, $2, $3, $4, $5, $6)`,
            [adminUserId, adminGroupId, childId, parseFloat(amount)||0, type, reason || null]
        );
        await logActivity(adminGroupId, childId || null, null, 'finance', 'balance_adjust', `הפרשת דמי כיס: ₪${amount} — ${reason || ''}`);
        res.json({ success: true });
    } catch(e) { res.status(500).json({ error: e.message }); }
});

