        const { title, reward, assignedTo, days, status, groupId, requireAiCheck, isRecurring, recurringDays, createdBy, priority } = req.body;
        const deadline = (!isRecurring && days) ? new Date(Date.now() + days * 24 * 60 * 60 * 1000) : null;
