// פרטי קהילה מלאים — משפחות, עסקים, מבצעים, FLOW
app.get('/api/zone-manager/community-detail/:id', verifyZoneManager, async (req, res) => {
    try {
        const { managerId } = req.zmSession;
        const commId = req.params.id;
        // אימות שהקהילה באזור של ZM זה
        const zoneCheck = await pool.query(
            `SELECT c.id, c.name, c.city, c.status, c.created_at, mz.name as zone_name
             FROM communities c JOIN manager_zones mz ON c.zone_id=mz.id
             WHERE c.id=$1 AND mz.manager_id=$2`, [commId, managerId]);
        if (!zoneCheck.rows.length) return res.status(403).json({ error: 'אין הרשאה לקהילה זו' });
        const comm = zoneCheck.rows[0];

        // משפחות (approved + pending)
        const families = await pool.query(
            `SELECT fc.group_id, fc.status, fc.is_community_manager,
                    fg.id, CASE WHEN fg.family_nickname IS NOT NULL AND fg.family_nickname != '' THEN fg.name || ' (' || fg.family_nickname || ')' ELSE fg.name END as name, fg.admin_email, fg.group_code
             FROM family_communities fc JOIN family_groups fg ON fg.id=fc.group_id
             WHERE fc.community_id=$1 ORDER BY fc.status DESC, fc.is_community_manager DESC, fg.name`, [commId]);

        // עסקים
        const businesses = await pool.query(
            `SELECT cb.business_id as id, cb.business_id, fg.name, fg.admin_email, cb.status, cb.discount_pct, cb.created_at
             FROM community_businesses cb JOIN family_groups fg ON fg.id=cb.business_id
             WHERE cb.community_id=$1 AND cb.status='approved' ORDER BY fg.name`, [commId]);

        // מבצעים פעילים
        const promos = await pool.query(
            `SELECT cp.id, cp.title, cp.discount_pct, cp.valid_until, cp.status,
                    fg.name as business_name
             FROM community_promotions cp JOIN family_groups fg ON fg.id=cp.business_id
             WHERE cp.community_id=$1 AND cp.status='approved'
             ORDER BY cp.created_at DESC LIMIT 10`, [commId]);

        // FLOW wallet של הקהילה
        const wallet = await pool.query(
            `SELECT balance FROM flow_wallets WHERE entity_type='community' AND entity_id=$1`, [commId]);

        // פעולות FLOW אחרונות
        const flowTx = await pool.query(
            `SELECT ft.action_key, ft.amount, ft.description, ft.created_at
             FROM flow_transactions ft
             WHERE ft.entity_type='community' AND ft.entity_id=$1
             ORDER BY ft.created_at DESC LIMIT 20`, [commId]);

        res.json({
            success: true,
            community: comm,
            families: families.rows,
            businesses: businesses.rows,
            promos: promos.rows,
            flowBalance: wallet.rows[0]?.balance || 0,
            flowTransactions: flowTx.rows
        });
    } catch(e) { res.status(500).json({ error: e.message }); }
});

