        const { reason } = req.body;
        await pool.query(`UPDATE sport_memberships SET status='frozen', frozen_at=CURRENT_DATE, frozen_reason=$1, updated_at=NOW() WHERE id=$2`, [reason||'', req.params.id]);
        res.json({ success: true });
