// הצעות שעסק הגיש לפולים
app.get('/api/biz/my-pool-bids/:bizGroupId', async (req, res) => {
    try {
        const r = await pool.query(`
            SELECT fpb.id as bid_id, fpb.price, fpb.description, fpb.status as bid_status, fpb.created_at as bid_at,
                   fp.id as pool_id, fp.title, fp.status as pool_status, fp.community_id,
                   fg_init.name as initiator_name, fp.initiator_id
            FROM flow_pool_bids fpb
            JOIN flow_pools fp ON fp.id = fpb.pool_id
            JOIN family_groups fg_init ON fg_init.id = fp.initiator_id
            WHERE fpb.business_group_id = $1
            ORDER BY fpb.created_at DESC
        `, [req.params.bizGroupId]);
        res.json({ success: true, bids: r.rows });
    } catch(e) { res.status(500).json({ error: e.message }); }
});

// ניקוי פולים שפג תוקפם (נקרא בחצות)
app.post('/api/community/pool/cleanup', async (req, res) => {
    try {
        const expired = await pool.query(`UPDATE flow_pools SET status='expired' WHERE status IN ('open_r1','open_r2') AND expires_at<=NOW() RETURNING id`);
        if (expired.rows.length) {
            const ids = expired.rows.map(r => r.id);
            await pool.query(`DELETE FROM flow_pool_messages WHERE pool_id = ANY($1::int[])`, [ids]);
        }
        res.json({ success: true, expired: expired.rows.length });
    } catch(e) { res.status(500).json({ error: e.message }); }
});

// פולים פתוחים בקהילות שהעסק חבר בהן
app.get('/api/biz/pools/:bizGroupId', async (req, res) => {
    try {
        // עדכון אוטומטי לסטטוס expired
        await pool.query(`
            UPDATE flow_pools SET status='expired'
            WHERE status IN ('open_r1','open_r2') AND expires_at <= NOW()
              AND community_id IN (SELECT community_id FROM community_businesses WHERE business_id=$1 AND status='approved')
        `, [req.params.bizGroupId]);

        // פולים פתוחים בקהילות שהעסק חבר בהן (לא מוסתרים)
        const r = await pool.query(`
            SELECT fp.*, fg.name as initiator_name,
                (SELECT COUNT(*) FROM flow_pool_members WHERE pool_id=fp.id) as member_count
            FROM flow_pools fp
            JOIN family_groups fg ON fg.id=fp.initiator_id
            JOIN community_businesses cb ON cb.community_id=fp.community_id AND cb.business_id=$1 AND cb.status='approved'
            WHERE fp.initiator_type='family'
              AND fp.status IN ('open_r1','open_r2')
              AND fp.id NOT IN (SELECT pool_id FROM biz_pool_hidden WHERE biz_group_id=$1)
            ORDER BY fp.created_at DESC`, [req.params.bizGroupId]);

        // פולים פגי תוקף שהעסק השתתף בהם ולא הסתיר
        const expiredR = await pool.query(`
            SELECT DISTINCT fp.*, fg.name as initiator_name,
                (SELECT COUNT(*) FROM flow_pool_members WHERE pool_id=fp.id) as member_count
            FROM flow_pools fp
            JOIN family_groups fg ON fg.id=fp.initiator_id
            WHERE fp.status = 'expired'
              AND fp.id NOT IN (SELECT pool_id FROM biz_pool_hidden WHERE biz_group_id=$1)
              AND fp.id IN (
                  SELECT pool_id FROM flow_pool_bids WHERE business_group_id=$1
                  UNION
                  SELECT pool_id FROM flow_pool_messages WHERE sender_id=$1 AND sender_type='business'
              )
            ORDER BY fp.created_at DESC
        `, [req.params.bizGroupId]);

        res.json({ success: true, pools: r.rows, expiredPools: expiredR.rows });
    } catch(e) { res.status(500).json({ error: e.message }); }
});

// ארכיב פולים לעסק — כל פולים מוארכבים שהעסק השתתף בהם
// ארכיב פולים למשפחה — פולים שהמשפחה יזמה ומוארכבים/סגורים
app.get('/api/community/pool/family-archive/:groupId', async (req, res) => {
    try {
        const r = await pool.query(`
            SELECT fp.id, fp.title, fp.description, fp.status, fp.max_price, fp.created_at,
                (SELECT COUNT(*) FROM flow_pool_members WHERE pool_id=fp.id) as members_count,
                (SELECT COUNT(*) FROM flow_pool_bids WHERE pool_id=fp.id) as bids_count
            FROM flow_pools fp
            WHERE fp.initiator_id=$1
              AND fp.status IN ('archived','closed')
            ORDER BY fp.created_at DESC
        `, [req.params.groupId]);
        res.json({ success: true, pools: r.rows });
    } catch(e) { res.status(500).json({ error: e.message }); }
});

// ארכיב פולים לעסק — פולים מ-biz_pool_hidden + פולים גלובלי archived שהעסק השתתף בהם
app.get('/api/biz/pool-archive/:bizGroupId', async (req, res) => {
    try {
        const r = await pool.query(`
            SELECT DISTINCT fp.id, fp.title, fp.description, fp.status, fp.created_at,
                fg.name as initiator_name,
                fpb.price as my_price, fpb.status as my_bid_status
            FROM flow_pools fp
            JOIN family_groups fg ON fg.id=fp.initiator_id
            LEFT JOIN flow_pool_bids fpb ON fpb.pool_id=fp.id AND fpb.business_group_id=$1
            WHERE (
                fp.id IN (SELECT pool_id FROM biz_pool_hidden WHERE biz_group_id=$1)
                OR (
                    fp.status = 'archived'
                    AND fp.id IN (
                        SELECT pool_id FROM flow_pool_bids WHERE business_group_id=$1
                        UNION
                        SELECT pool_id FROM flow_pool_messages WHERE sender_id=$1 AND sender_type='business'
                    )
                )
            )
            ORDER BY fp.created_at DESC
        `, [req.params.bizGroupId]);
        res.json({ success: true, pools: r.rows });
    } catch(e) { res.status(500).json({ error: e.message }); }
});

