// GET available banner slots for a business (filtered by community)
app.get('/api/biz/banner/slots', async (req, res) => {
    try {
        const { communityId } = req.query;
        const slots = await pool.query(`
            SELECT DISTINCT bs.*
            FROM banner_slots bs
            WHERE bs.is_active=TRUE
              AND (
                NOT EXISTS (SELECT 1 FROM banner_slot_communities bsc WHERE bsc.slot_id=bs.id)
                ${communityId ? `OR EXISTS (SELECT 1 FROM banner_slot_communities bsc WHERE bsc.slot_id=bs.id AND bsc.community_id=$1)` : ''}
              )
            ORDER BY bs.id
        `, communityId ? [communityId] : []);
        const slotIds = slots.rows.map(s=>s.id);
        const pricing = await pool.query(`
            SELECT * FROM banner_pricing WHERE slot_id=ANY($1) ORDER BY slot_id,community_count,duration_days
        `, [slotIds]);
        const communities = await pool.query(`
            SELECT bsc.slot_id, c.id, c.name FROM banner_slot_communities bsc
            JOIN communities c ON c.id=bsc.community_id WHERE bsc.slot_id=ANY($1) ORDER BY c.name
        `, [slotIds]);
        const pMap = {};
        pricing.rows.forEach(p => { if(!pMap[p.slot_id]) pMap[p.slot_id]=[]; pMap[p.slot_id].push(p); });
        const cMap = {};
        communities.rows.forEach(r => { if(!cMap[r.slot_id]) cMap[r.slot_id]=[]; cMap[r.slot_id].push({id:r.id,name:r.name}); });
        // if a slot has no assigned communities, load all communities as options
        const slotsWithoutComm = slots.rows.filter(s => !cMap[s.id] || !cMap[s.id].length).map(s=>s.id);
        let allComms = { rows: [] };
        if (slotsWithoutComm.length) {
            allComms = await pool.query(`SELECT id, name FROM communities ORDER BY name`);
        }
        const rateCfg = await pool.query(`SELECT personal_amount FROM flow_config WHERE key='flow_to_ils_rate' LIMIT 1`).catch(()=>({rows:[]}));
        const flow_rate = parseFloat(rateCfg.rows[0]?.personal_amount || 100);
        res.json({success:true, slots: slots.rows.map(s=>({
            ...s,
            pricing: pMap[s.id]||[],
            communities: cMap[s.id]?.length ? cMap[s.id] : allComms.rows
        })), flow_rate});
    } catch(e) { res.status(500).json({error:e.message}); }
});

// POST submit banner order (business)
app.post('/api/biz/banner/orders', async (req, res) => {
    try {
        const { business_id, slot_id, community_ids, duration_days, payment_method, notes,
                coins_used: clientCoins, cash_amount: clientCash, total_price_ils: clientTotal } = req.body;
        if (!business_id || !slot_id || !duration_days) return res.status(400).json({error:'שדות חסרים'});

        // validate pricing exists — prefer community_count match, fallback to 0
        const commCount = Array.isArray(community_ids) ? community_ids.length : 0;
        const pricingExact = await pool.query(
            `SELECT * FROM banner_pricing WHERE slot_id=$1 AND duration_days=$2 AND community_count=$3`, [slot_id, duration_days, commCount]
        );
        const pricingBase = pricingExact.rows.length ? pricingExact : await pool.query(
            `SELECT * FROM banner_pricing WHERE slot_id=$1 AND duration_days=$2 AND (community_count=0 OR community_count IS NULL)`, [slot_id, duration_days]
        );
        if (!pricingBase.rows.length) return res.status(400).json({error:'מחירון לא נמצא'});
        const p = pricingBase.rows[0];
        const total_price_ils = parseFloat(p.price_ils);

        // validate coin balance if coins used
        let coins_used = Math.max(0, parseFloat(clientCoins) || 0);
        let cash_amount = parseFloat(clientCash) ?? Math.max(0, total_price_ils - coins_used * (10/100));
        if (coins_used > 0) {
            const wallet = await pool.query(
                `SELECT COALESCE(balance,0) as balance FROM flow_wallets WHERE entity_type='business' AND entity_id=$1`, [business_id]
            );
            const bal = parseFloat(wallet.rows[0]?.balance || 0);
            if (coins_used > bal) return res.status(400).json({error:`יתרת מטבעות לא מספיקה (יתרה: ${bal.toFixed(0)})`});
        }

        const r = await pool.query(
            `INSERT INTO banner_orders(business_id,slot_id,community_ids,duration_days,total_price_ils,coins_used,cash_amount,payment_method,notes)
             VALUES($1,$2,$3,$4,$5,$6,$7,$8,$9) RETURNING *`,
            [business_id, slot_id, JSON.stringify(community_ids||[]), duration_days,
             total_price_ils, coins_used, cash_amount, payment_method||'mixed', notes||'']
        );
        res.json({success:true, order:r.rows[0]});
    } catch(e) { res.status(500).json({error:e.message}); }
});

