// ─── KIDS OVERVIEW (parent dashboard) ────────────────────────────────────────
app.get('/api/kids/parent-overview/:groupId', async (req, res) => {
  try {
    const gid = req.params.groupId;

    // ילדים + יתרת FLW
    const kids = await pool.query(`
      SELECT u.id, u.nickname, u.role, u.birth_year,
        CASE WHEN EXISTS(SELECT 1 FROM information_schema.columns WHERE table_name='users' AND column_name='profile_image') THEN u.profile_image ELSE NULL END as profile_image,
        COALESCE(w.balance_flw, 0) as flw_balance
      FROM users u
      LEFT JOIN flw_kid_wallets w ON w.child_user_id = u.id
      WHERE u.group_id = $1 AND u.role = 'CHILD' AND u.status = 'active'
      ORDER BY u.nickname
    `, [gid]);

    // אתגרים (kid_quests) per child — פתוחים
    const openQuests = await pool.query(`
      SELECT kq.child_user_id, COUNT(*) as open_count
      FROM kid_quests kq
      LEFT JOIN kid_quest_results kr ON kr.quest_id = kq.id
      WHERE kq.family_group_id = $1 AND kr.id IS NULL
      GROUP BY kq.child_user_id
    `, [gid]);

    // אתגרים academy (user_assignments) פתוחים
    const openAcademy = await pool.query(`
      SELECT ua.user_id, COUNT(*) as open_count
      FROM user_assignments ua
      JOIN users u ON u.id = ua.user_id AND u.group_id = $1
      WHERE ua.status = 'assigned'
      GROUP BY ua.user_id
    `, [gid]);

    // משחקים מוקצים לכל ילד
    const gamesPerKid = await pool.query(`
      SELECT ga.child_user_id, gc.title as game_name, gc.thumbnail_emoji as icon,
        ga.rounds_used, ga.rounds_total, ga.status, ga.flw_per_round,
        ga.assigned_at, ga.expires_at
      FROM game_assignments ga
      JOIN games_catalog gc ON gc.id = ga.game_id
      JOIN users u ON u.id = ga.child_user_id AND u.group_id = $1
      WHERE ga.status IN ('active','completed')
      ORDER BY ga.assigned_at DESC
    `, [gid]);

    // סיכום כללי — kid_quests + user_assignments
    const totalOpen = await pool.query(`
      SELECT
        (SELECT COUNT(*) FROM kid_quests kq
         LEFT JOIN kid_quest_results kr ON kr.quest_id = kq.id
         WHERE kq.family_group_id = $1 AND kr.id IS NULL)
        +
        (SELECT COUNT(*) FROM user_assignments ua
         JOIN users u ON u.id = ua.user_id AND u.group_id = $1
         WHERE ua.status = 'assigned')
      AS cnt
    `, [gid]);

    // היסטוריית פעילות אתגרים
    const history = await pool.query(`
      SELECT
        kq.id, kq.title, kq.subject, kq.created_at,
        kq.flw_reward,
        u.nickname as child_name,
        cu.nickname as created_by_name,
        kr.score, kr.completed_at
      FROM kid_quests kq
      LEFT JOIN users u ON u.id = kq.child_user_id
      LEFT JOIN users cu ON cu.id = kq.created_by
      LEFT JOIN kid_quest_results kr ON kr.quest_id = kq.id
      WHERE kq.family_group_id = $1
      ORDER BY COALESCE(kr.completed_at, kq.created_at) DESC
      LIMIT 50
    `, [gid]);

    // אתגרים מפורטים לכל ילד
    const questsDetail = await pool.query(`
      SELECT kq.child_user_id, kq.id, kq.title, kq.subject, kq.flw_reward,
        kq.created_at,
        kr.completed_at, kr.score
      FROM kid_quests kq
      LEFT JOIN kid_quest_results kr ON kr.quest_id = kq.id
      JOIN users u ON u.id = kq.child_user_id AND u.group_id = $1
      ORDER BY kq.created_at DESC
    `, [gid]);

    const questsMap = {};
    questsDetail.rows.forEach(r => {
      if (!questsMap[r.child_user_id]) questsMap[r.child_user_id] = [];
      questsMap[r.child_user_id].push(r);
    });

    const openQuestsMap = {};
    openQuests.rows.forEach(r => { openQuestsMap[r.child_user_id] = parseInt(r.open_count); });
    const openAcademyMap = {};
    openAcademy.rows.forEach(r => { openAcademyMap[r.user_id] = parseInt(r.open_count); });

    const gamesMap = {};
    gamesPerKid.rows.forEach(r => {
      if (!gamesMap[r.child_user_id]) gamesMap[r.child_user_id] = [];
      gamesMap[r.child_user_id].push(r);
    });

    const kidsData = kids.rows.map(k => ({
      ...k,
      open_quests: (openQuestsMap[k.id] || 0) + (openAcademyMap[k.id] || 0),
      games: gamesMap[k.id] || [],
      quests: questsMap[k.id] || []
    }));

    res.json({
      success: true,
      kids: kidsData,
      totalOpen: parseInt(totalOpen.rows[0]?.cnt || 0),
      history: history.rows
    });
  } catch(e) { res.status(500).json({ error: e.message }); }
});

// שמירת תמונת פרופיל לילד (URL מ-Cloudinary, או dataUrl כ-fallback)
app.post('/api/kids/profile-image/:userId', async (req, res) => {
  try {
    let { imageUrl, dataUrl } = req.body;
    if (!imageUrl && dataUrl) {
      // fallback: שמור לדיסק
      if (!dataUrl.startsWith('data:image/')) return res.status(400).json({ error: 'invalid image' });
      const ext = dataUrl.match(/^data:image\/(\w+);/)?.[1] || 'jpg';
      const filename = `avatar_${req.params.userId}_${Date.now()}.${ext}`;
      const dest = path.join(__dirname, 'public', 'uploads', 'avatars', filename);
      fs.writeFileSync(dest, Buffer.from(dataUrl.replace(/^data:image\/\w+;base64,/, ''), 'base64'));
      imageUrl = `/uploads/avatars/${filename}`;
    }
    if (!imageUrl) return res.status(400).json({ error: 'missing image' });
    await pool.query('UPDATE users SET profile_image=$1 WHERE id=$2', [imageUrl, req.params.userId]);
    res.json({ success: true, url: imageUrl });
  } catch(e) { res.status(500).json({ error: e.message }); }
});

