// ─── FAMILY WEEKLY REPORT ─────────────────────────────────────────────────────
app.get('/api/family/weekly-report/:groupId', async (req, res) => {
  try {
    const groupId = req.params.groupId;
    const weeksAgo = parseInt(req.query.weeks||'0');
    const endDate = new Date();
    endDate.setDate(endDate.getDate() - weeksAgo*7);
    const startDate = new Date(endDate);
    startDate.setDate(startDate.getDate() - 7);
    const prevStart = new Date(startDate);
    prevStart.setDate(prevStart.getDate() - 7);

    const children = await pool.query(`
      SELECT u.id, u.nickname, u.birth_year,
        COALESCE(w.balance_flw,0) as balance_flw,
        COALESCE(w.lifetime_flw,0) as lifetime_flw
      FROM users u
      LEFT JOIN flw_kid_wallets w ON w.child_user_id=u.id
      WHERE u.group_id=$1 AND u.role != 'ADMIN' AND u.status='active'
    `, [groupId]);

    const report = [];

    for(const child of children.rows){
      const cid = child.id;

      const flwWeek = await pool.query(`
        SELECT COALESCE(SUM(flw_earned),0) as total FROM (
          SELECT flw_earned FROM game_sessions
          WHERE child_user_id=$1 AND played_at BETWEEN $2 AND $3
          UNION ALL
          SELECT flw_earned FROM kid_quest_results
          WHERE child_user_id=$1 AND completed_at BETWEEN $2 AND $3
        ) t
      `, [cid, startDate, endDate]);

      const flwPrev = await pool.query(`
        SELECT COALESCE(SUM(flw_earned),0) as total FROM (
          SELECT flw_earned FROM game_sessions
          WHERE child_user_id=$1 AND played_at BETWEEN $2 AND $3
          UNION ALL
          SELECT flw_earned FROM kid_quest_results
          WHERE child_user_id=$1 AND completed_at BETWEEN $2 AND $3
        ) t
      `, [cid, prevStart, startDate]);

      const games = await pool.query(`
        SELECT g.title, g.subject, g.thumbnail_emoji,
          COUNT(*) as plays,
          AVG(gs.score)::INT as avg_score,
          SUM(gs.flw_earned) as flw_earned
        FROM game_sessions gs
        LEFT JOIN games_catalog g ON g.id=gs.game_id
        WHERE gs.child_user_id=$1 AND gs.played_at BETWEEN $2 AND $3
        GROUP BY gs.game_id, g.title, g.subject, g.thumbnail_emoji
        ORDER BY plays DESC
      `, [cid, startDate, endDate]);

      const quests = await pool.query(`
        SELECT kq.title, kq.subject, kr.score, kr.flw_earned, kr.completed_at
        FROM kid_quest_results kr
        JOIN kid_quests kq ON kq.id=kr.quest_id
        WHERE kr.child_user_id=$1 AND kr.completed_at BETWEEN $2 AND $3
        ORDER BY kr.completed_at DESC
      `, [cid, startDate, endDate]);

      const subjects = {};
      for(const g of games.rows){
        if(!subjects[g.subject]) subjects[g.subject]={scores:[],emoji:g.thumbnail_emoji};
        subjects[g.subject].scores.push(g.avg_score||0);
      }
      for(const q of quests.rows){
        if(!subjects[q.subject]) subjects[q.subject]={scores:[],emoji:'📝'};
        subjects[q.subject].scores.push(q.score||0);
      }
      const subjectSummary = Object.entries(subjects).map(([sub,data])=>({
        subject:sub, emoji:data.emoji,
        avg:Math.round(data.scores.reduce((a,b)=>a+b,0)/data.scores.length)
      })).sort((a,b)=>b.avg-a.avg);

      const recommendations = [];
      const flwDelta = parseInt(flwWeek.rows[0].total)-parseInt(flwPrev.rows[0].total);
      if(games.rows.length===0)
        recommendations.push({type:'warn',text:`${child.nickname} לא שיחק השבוע — הקצה משחק חדש`});
      if(quests.rows.length===0)
        recommendations.push({type:'info',text:`שלח קווסט ל${child.nickname} כדי לעודד למידה`});
      if(subjectSummary.length>0 && subjectSummary[subjectSummary.length-1].avg<60)
        recommendations.push({type:'warn',text:`${child.nickname} מתקשה ב${subjectSummary[subjectSummary.length-1].subject} — נסה קווסט קל יותר`});
      if(subjectSummary.length>0 && subjectSummary[0].avg>=85)
        recommendations.push({type:'good',text:`${child.nickname} מצטיין ב${subjectSummary[0].subject}! נסה נושא חדש`});
      if(flwDelta>0)
        recommendations.push({type:'good',text:`${child.nickname} צבר ${flwDelta} FLW יותר מהשבוע שעבר 🚀`});
      if(flwDelta<-20)
        recommendations.push({type:'warn',text:`ירידה של ${Math.abs(flwDelta)} FLW — שאל איך אפשר לעזור`});

      report.push({
        child, flwWeek:parseInt(flwWeek.rows[0].total),
        flwPrev:parseInt(flwPrev.rows[0].total), flwDelta,
        games:games.rows, quests:quests.rows,
        subjects:subjectSummary, recommendations
      });
    }

    res.json({ success:true, report,
      period:{ start:startDate, end:endDate, weeksAgo } });
  } catch(e){ res.status(500).json({ error:e.message }); }
});

// ===== COMMUNITY FEED API =====

// שליפת פיד
app.get('/api/community/feed', async (req, res) => {
  try {
    const { familyId, communityId, groupId, page=1, limit=20 } = req.query;
    const fid = parseInt(familyId) || 0;
    const lim = parseInt(limit) || 20;
    const off = (parseInt(page)-1) * lim;

    // בניית WHERE דינמי
    const conditions = ['cp.is_hidden=false'];
    const params = [];

    if (communityId) {
      params.push(parseInt(communityId));
      conditions.push(`cp.community_id=$${params.length}`);
    } else if (fid) {
      params.push(fid);
      conditions.push(`cp.community_id IN (SELECT community_id FROM family_communities WHERE group_id=$${params.length})`);
    }
    if (groupId) {
      params.push(parseInt(groupId));
      conditions.push(`cp.group_id=$${params.length}`);
    }
    params.push(fid, lim, off);
    const pFid = params.length - 2; // index of fid param for EXISTS
    const pLim = params.length - 1;
    const pOff = params.length;

    const posts = await pool.query(`
      SELECT
        cp.*,
        CASE WHEN fg.family_nickname IS NOT NULL AND fg.family_nickname != ''
             THEN fg.name || ' (' || fg.family_nickname || ')'
             ELSE fg.name END as author_name,
        fg.image_url as author_avatar,
        c.name as community_name,
        cig.name as group_name,
        cig.icon_emoji as group_icon,
        (SELECT CASE WHEN TRIM(COALESCE(first_name,'') || ' ' || COALESCE(last_name,'')) != '' THEN TRIM(COALESCE(first_name,'') || ' ' || COALESCE(last_name,'')) ELSE COALESCE(nickname,'') END
         FROM users WHERE id=cp.author_user_id LIMIT 1) as author_user_name,
        (SELECT TRIM(COALESCE(first_name,'') || ' ' || COALESCE(last_name,''))
         FROM users WHERE group_id=cp.author_family_id AND role='ADMIN' LIMIT 1) as publisher_name,
        EXISTS(SELECT 1 FROM community_post_likes
               WHERE post_id=cp.id AND family_id=$${pFid}) as liked_by_me
      FROM community_posts cp
      JOIN family_groups fg ON fg.id = cp.author_family_id
      JOIN communities c ON c.id = cp.community_id
      LEFT JOIN community_interest_groups cig ON cig.id = cp.group_id
      WHERE ${conditions.join(' AND ')}
      ORDER BY cp.is_pinned DESC,
               (cp.likes_count*3 + cp.comments_count*5 + cp.shares_count*4
                + 100.0/(EXTRACT(EPOCH FROM (NOW()-cp.created_at))/3600 + 2)) DESC
      LIMIT $${pLim} OFFSET $${pOff}
    `, params);

    res.json({ success:true, posts: posts.rows, hasMore: posts.rows.length === parseInt(limit) });
  } catch(e){ console.error('FEED ERROR:', e.message); res.status(500).json({ error:e.message }); }
});

// יצירת פוסט
app.post('/api/community/posts', async (req, res) => {
  try {
    const { familyId, communityId, groupId, postType='general', content, imageUrl, userId } = req.body;
    if(!content?.trim()) return res.status(400).json({ error: 'תוכן ריק' });

    const member = await pool.query(
      `SELECT group_id FROM family_communities WHERE group_id=$1 AND community_id=$2`,
      [familyId, communityId]
    );
    if(!member.rows[0]) return res.status(403).json({ error: 'לא חבר בקהילה' });

    const post = await pool.query(`
      INSERT INTO community_posts (author_family_id, author_user_id, community_id, group_id, post_type, content, image_url)
      VALUES ($1,$2,$3,$4,$5,$6,$7) RETURNING *
    `, [familyId, userId||null, communityId, groupId||null, postType, content.trim(), imageUrl||null]);

    try { await pool.query(
      `INSERT INTO flow_transactions (entity_id, entity_type, action_key, amount, community_id) VALUES ($1,'family','community_post',3,$2)`,
      [familyId, communityId]
    ); } catch(e){}
    try { await pool.query(
      `INSERT INTO flow_transactions (entity_id, entity_type, action_key, amount, community_id) VALUES ($1,'community','community_post_community',1,$1)`,
      [communityId]
    ); } catch(e){}

    if(groupId){
      await pool.query('UPDATE community_interest_groups SET posts_count=posts_count+1 WHERE id=$1', [groupId]);
    }

    res.json({ success:true, post: post.rows[0] });
  } catch(e){ res.status(500).json({ error:e.message }); }
});

// סימון פיד כנקרא
app.post('/api/community/feed/mark-read', async (req, res) => {
  try {
    const { familyId, communityId } = req.body;
    if (!familyId) return res.status(400).json({ error: 'familyId נדרש' });
    if (communityId) {
      await pool.query(
        `INSERT INTO community_feed_reads (family_id, community_id, last_read_at)
         VALUES ($1,$2,NOW())
         ON CONFLICT (family_id, community_id) DO UPDATE SET last_read_at=NOW()`,
        [familyId, communityId]
      );
    } else {
      // סמן כל הקהילות
      const comms = await pool.query(
        `SELECT community_id FROM family_communities WHERE group_id=$1 AND status='approved'`, [familyId]
      );
      for (const row of comms.rows) {
        await pool.query(
          `INSERT INTO community_feed_reads (family_id, community_id, last_read_at)
           VALUES ($1,$2,NOW())
           ON CONFLICT (family_id, community_id) DO UPDATE SET last_read_at=NOW()`,
          [familyId, row.community_id]
        );
      }
    }
    res.json({ success: true });
  } catch(e) { res.status(500).json({ error: e.message }); }
});

// ספירת פוסטים לא נקראו
app.get('/api/community/feed/unread-counts', async (req, res) => {
  try {
    const { familyId } = req.query;
    if (!familyId) return res.status(400).json({ error: 'familyId נדרש' });
    const comms = await pool.query(
      `SELECT community_id FROM family_communities WHERE group_id=$1 AND status='approved'`, [familyId]
    );
    const counts = {};
    let total = 0;
    for (const row of comms.rows) {
      const cid = row.community_id;
      const readRes = await pool.query(
        `SELECT last_read_at FROM community_feed_reads WHERE family_id=$1 AND community_id=$2`, [familyId, cid]
      );
      let cnt = 0;
      if (readRes.rows[0]) {
        const r = await pool.query(
          `SELECT COUNT(*) as cnt FROM community_posts WHERE community_id=$1 AND created_at > $2 AND is_hidden=false`,
          [cid, readRes.rows[0].last_read_at]
        );
        cnt = parseInt(r.rows[0].cnt);
      }
      counts[cid] = cnt;
      total += cnt;
    }
    res.json({ counts, total });
  } catch(e) { res.status(500).json({ error: e.message }); }
});

