// ===== LIVE GAMES API =====

function generateGameCode() {
  const chars = 'ABCDEFGHJKLMNPQRSTUVWXYZ23456789';
  let code = '';
  for (let i = 0; i < 6; i++) code += chars[Math.floor(Math.random() * chars.length)];
  return code;
}

// יצירת משחק
app.post('/api/live-games', verifySA, async (req, res) => {
  try {
    const { title, prize, business_name, sponsor_name, sponsor_text, whatsapp_text, is_public, community_id, questions, sponsor_logo_data, character_image_data } = req.body;
    if (!title) return res.status(400).json({ error: 'כותרת חובה' });
    let code;
    for (let i = 0; i < 10; i++) {
      code = generateGameCode();
      const exists = await pool.query('SELECT id FROM live_games WHERE game_code=$1', [code]);
      if (!exists.rows.length) break;
    }
    const g = await pool.query(
      `INSERT INTO live_games (title, prize, business_name, sponsor_name, sponsor_text, whatsapp_text, is_public, community_id, game_code, status) VALUES ($1,$2,$3,$4,$5,$6,$7,$8,$9,'waiting') RETURNING *`,
      [title, prize || null, business_name || null, sponsor_name||null, sponsor_text||null, whatsapp_text||null, !!is_public, community_id||null, code]
    );
    const gameId = g.rows[0].id;
    // שמירת תמונות ישירות ב-DB (עמיד בפני restart)
    const sponsorLogo = sponsor_logo_data || null;
    const characterImage = character_image_data || null;
    if (sponsorLogo || characterImage) {
      await pool.query('UPDATE live_games SET sponsor_logo=$1, character_image=$2, img_version=1 WHERE id=$3', [sponsorLogo, characterImage, gameId]);
    }
    if (questions && questions.length) {
      for (let i = 0; i < questions.length; i++) {
        const q = questions[i];
        await pool.query(
          `INSERT INTO live_game_questions (game_id, question, opts, correct_index, time_seconds, order_num) VALUES ($1,$2,$3,$4,$5,$6)`,
          [gameId, q.question, JSON.stringify(q.opts), q.correct_index, q.time_seconds || 20, i]
        );
      }
    }
    res.json({ success: true, game: g.rows[0] });
  } catch(e) { res.status(500).json({ error: e.message }); }
});

// עדכון משחק
app.put('/api/live-games/:id', verifySA, async (req, res) => {
  try {
    const { title, prize, business_name, sponsor_name, sponsor_text, whatsapp_text, is_public, is_hidden, community_id, questions, sponsor_logo_data, character_image_data } = req.body;
    const gid = parseInt(req.params.id, 10);
    if (!gid) return res.status(400).json({ error: 'מזהה משחק לא תקין' });
    // שמירת תמונות חדשות ב-DB אם הועלו
    const baseParams = [title, prize || null, business_name || null, sponsor_name||null, sponsor_text||null, whatsapp_text||null, !!is_public, !!is_hidden, community_id||null, gid];
    let logoSet = '', charSet = '', versionBump = '';
    if (sponsor_logo_data) { baseParams.push(sponsor_logo_data); logoSet = `, sponsor_logo=$${baseParams.length}`; }
    if (character_image_data) { baseParams.push(character_image_data); charSet = `, character_image=$${baseParams.length}`; }
    if (sponsor_logo_data || character_image_data) versionBump = ', img_version=img_version+1';
    await pool.query(`UPDATE live_games SET title=$1, prize=$2, business_name=$3, sponsor_name=$4, sponsor_text=$5, whatsapp_text=$6, is_public=$7, is_hidden=$8, community_id=$9${logoSet}${charSet}${versionBump} WHERE id=$10`,
      baseParams);
    // מעדכן שאלות רק אם הגיעו שאלות — מניעת מחיקה בשגגה כשהמערך ריק
    if (Array.isArray(questions) && questions.length > 0) {
      await pool.query('DELETE FROM live_game_questions WHERE game_id=$1', [gid]);
      for (let i = 0; i < questions.length; i++) {
        const q = questions[i];
        await pool.query(
          `INSERT INTO live_game_questions (game_id, question, opts, correct_index, time_seconds, order_num) VALUES ($1,$2,$3,$4,$5,$6)`,
          [gid, q.question, JSON.stringify(q.opts), q.correct_index, q.time_seconds || 20, i]
        );
      }
    }
    const cur = await pool.query('SELECT status FROM live_games WHERE id=$1', [gid]);
    res.json({ success: true, status: cur.rows[0]?.status });
  } catch(e) { res.status(500).json({ error: e.message }); }
});

