app.post('/api/live-games/:game_code/join', async (req, res) => {
  try {
    const { userId, displayName, groupId, joinSource } = req.body;
    const g = await pool.query(`SELECT * FROM live_games WHERE game_code=$1`, [req.params.game_code.toUpperCase()]);
    if (!g.rows.length) return res.status(404).json({ error: 'משחק לא נמצא' });
    const game = g.rows[0];
    if (game.is_hidden) return res.status(403).json({ error: 'המשחק אינו זמין' });
    if (game.status === 'disabled') return res.status(403).json({ error: 'המשחק הסתיים' });
    if (game.status === 'ended') return res.status(403).json({ error: 'המשחק הסתיים' });
    // insert participant — approved=false until admin approves
    await pool.query(
      `INSERT INTO live_game_participants (game_id, user_id, display_name, group_id, approved, join_source) VALUES ($1,$2,$3,$4,false,$5) ON CONFLICT (game_id, user_id) DO NOTHING`,
      [game.id, userId || null, displayName || 'אנונימי', groupId || null, joinSource || null]
    );
    // check if already approved (returning participant)
    const existing = await pool.query('SELECT approved FROM live_game_participants WHERE game_id=$1 AND user_id=$2', [game.id, userId || null]);
    const approved = existing.rows[0]?.approved || false;
    res.json({ success: true, game_id: game.id, status: game.status, approved,
      sponsor_name: game.sponsor_name, sponsor_text: game.sponsor_text, title: game.title, prize: game.prize });
  } catch(e) { res.status(500).json({ error: e.message }); }
});

// שליחת תשובה
app.post('/api/live-games/:game_code/answer', async (req, res) => {
  try {
    const { userId, questionId, answerIndex, responseTimeMs } = req.body;
    const g = await pool.query(`SELECT * FROM live_games WHERE game_code=$1`, [req.params.game_code.toUpperCase()]);
    if (!g.rows.length) return res.status(404).json({ error: 'משחק לא נמצא' });
    const game = g.rows[0];
    const q = await pool.query('SELECT * FROM live_game_questions WHERE id=$1 AND game_id=$2', [questionId, game.id]);
    if (!q.rows.length) return res.status(404).json({ error: 'שאלה לא נמצאה' });
    const question = q.rows[0];
    const isTimeout = parseInt(answerIndex) === -1;
    const isCorrect = !isTimeout && parseInt(answerIndex) === question.correct_index;
    // חסימת תשובה כפולה
    const dup = await pool.query('SELECT id FROM live_game_answers WHERE question_id=$1 AND user_id=$2', [questionId, userId]);
    if (dup.rows.length) return res.json({ success: true, already_answered: true, is_correct: isCorrect, correct_index: question.correct_index });
    if (isTimeout) return res.json({ success: true, is_correct: false, correct_index: question.correct_index });
    await pool.query(
      `INSERT INTO live_game_answers (game_id, question_id, user_id, answer_index, is_correct, response_time_ms) VALUES ($1,$2,$3,$4,$5,$6)`,
      [game.id, questionId, userId || null, answerIndex, isCorrect, responseTimeMs || null]
    );
    if (isCorrect) {
      // ניקוד לפי מהירות תגובה (מקסימום 1000, מינימום 100)
      const timeSec = question.time_seconds || 20;
      const speed = Math.max(0, timeSec * 1000 - (responseTimeMs || 0));
      const score = Math.round(100 + (speed / (timeSec * 1000)) * 900);
      await pool.query(
        `UPDATE live_game_participants SET score = score + $1 WHERE game_id=$2 AND user_id=$3`,
        [score, game.id, userId]
      );
    }
    res.json({ success: true, is_correct: isCorrect, correct_index: question.correct_index });
  } catch(e) { res.status(500).json({ error: e.message }); }
});

// הגשת תמונות משחק מה-DB (עמיד בפני restart)
async function _serveGameImage(res, data) {
  res.set('Cache-Control', 'no-store'); // תמיד טרי — חשוב אחרי עדכון תמונה
  if (!data) return res.status(404).end();
  if (data.startsWith('data:')) {
    const semi = data.indexOf(';base64,');
    if (semi === -1) return res.status(400).end();
    const mime = data.slice(5, semi);
    const b64 = data.slice(semi + 8).trim();
    const buf = Buffer.from(b64, 'base64');
    return res.set('Content-Type', mime).send(buf);
  }
  // נתיב ישן — נסה לשרת מהקובץ
  const filePath = path.join(__dirname, 'public', data);
  if (fs.existsSync(filePath)) return res.sendFile(filePath);
  res.status(404).end();
}
