app.get('/api/community/:id/live-games', async (req, res) => {
  try {
    const communityId = req.params.id;
    const groupId = req.query.groupId || null;
    let rows;
    if (groupId) {
      // שלוף את כל קהילות המשפחה המאושרות — גם מטבלת family_communities וגם מ-family_groups.community_id
      const commRes = await pool.query(
        `SELECT community_id FROM family_communities WHERE group_id=$1 AND status='approved'
         UNION
         SELECT community_id FROM family_groups WHERE id=$1 AND community_id IS NOT NULL`,
        [groupId]
      );
      const commIds = commRes.rows.map(r => r.community_id);
      // כולל: משחקים פומביים לכל הקהילות + לקהילות של המשפחה + שויכו ישירות לקבוצה
      rows = await pool.query(
        `SELECT DISTINCT id, title, prize, business_name, sponsor_name, sponsor_text, game_code, status
         FROM live_games
         WHERE is_hidden=false AND status IN ('waiting','active')
           AND (
             (is_public=true AND (community_id IS NULL OR community_id = ANY($1)))
             OR id IN (SELECT game_id FROM live_game_assignments WHERE group_id=$2)
           )
         ORDER BY id DESC LIMIT 10`,
        [commIds.length > 0 ? commIds : [0], groupId]
      );
    } else {
      rows = await pool.query(
        `SELECT id, title, prize, business_name, sponsor_name, sponsor_text, game_code, status
         FROM live_games
         WHERE is_public=true AND is_hidden=false AND status IN ('waiting','active')
           AND (community_id IS NULL OR community_id=$1)
         ORDER BY created_at DESC LIMIT 10`,
        [communityId]
      );
    }
    res.json({ games: rows.rows });
  } catch(e) { res.status(500).json({ error: e.message }); }
});

