// POST /api/kol-haam/comments/:id/pin — pin by content author
app.post('/api/kol-haam/comments/:id/pin', verifyFamily, async (req, res) => {
    const { id } = req.params;
    // const { user_id } = req.body; // ← ישן — rollback: החזר שורה זו
    // user_id מגיע מהטוקן בלבד; בדיקת בעלות מול כותב הכתבה נוספה (לא הייתה קודם)
    try {
        // שלוף את התגובה + family_group_id של כותב הכתבה המקורית
        const { rows } = await pool.query(`
            SELECT cc.is_pinned_by_author, ap.family_group_id
            FROM content_comments cc
            JOIN content_items ci ON ci.id = cc.content_item_id
            JOIN author_profiles ap ON ap.id = ci.author_profile_id
            WHERE cc.id=$1
        `, [id]);
        if (!rows.length) return res.json({ success: false, error: 'לא נמצא' });
        // רק כותב הכתבה (לא כותב התגובה) יכול לפין
        if (String(rows[0].family_group_id) !== String(req.familyAuth.groupId))
            return res.json({ success: false, error: 'רק כותב הכתבה יכול לסמן תגובה' });
        const newPin = !rows[0].is_pinned_by_author;
        await pool.query(`UPDATE content_comments SET is_pinned_by_author=$1 WHERE id=$2`, [newPin, id]);
        res.json({ success: true, pinned: newPin });
    } catch(e) { res.json({ success: false, error: e.message }); }
});

// POST /api/kol-haam/content/:id/mark-solution/:comment_id
app.post('/api/kol-haam/content/:id/mark-solution/:comment_id', verifyFamily, async (req, res) => {
    const { id, comment_id } = req.params;
    // const { user_id } = req.body; // ← ישן — rollback: החזר שורה זו
    // user_id מגיע מהטוקן; בדיקת בעלות מפושטת — groupId ישירות מהטוקן במקום lookup נוסף ל-users
    try {
        const { rows: ci } = await pool.query(`SELECT content_type, author_profile_id FROM content_items WHERE id=$1`, [id]);
        if (!ci.length) return res.json({ success: false, error: 'לא נמצא' });
        if (ci[0].content_type !== 'QA_QUESTION') return res.json({ success: false, error: 'רק שאלות תומכות בסימון פתרון' });
        // verify requester is the content author — groupId מהטוקן, לא צריך lookup ל-users
        const { rows: ap } = await pool.query(`SELECT family_group_id FROM author_profiles WHERE id=$1`, [ci[0].author_profile_id]);
        if (!ap.length || String(ap[0].family_group_id) !== String(req.familyAuth.groupId))
            return res.json({ success: false, error: 'רק כותב השאלה יכול לסמן פתרון' });
        // clear previous solution
        await pool.query(`UPDATE content_comments SET is_solution_marked=false WHERE content_item_id=$1`, [id]);
        // mark new solution
        await pool.query(`UPDATE content_comments SET is_solution_marked=true WHERE id=$1`, [comment_id]);
        res.json({ success: true });
    } catch(e) { res.json({ success: false, error: e.message }); }
});

// POST /api/kol-haam/comments/:id/upvote-solution
app.post('/api/kol-haam/comments/:id/upvote-solution', verifyFamily, async (req, res) => {
    const { id } = req.params;
    // const { user_id } = req.body; // ← ישן — rollback: החזר שורה זו
    const user_id = req.familyAuth.userId;
    if (!user_id) return res.json({ success: false, error: 'missing user_id' });
    try {
        const { rows } = await pool.query(`SELECT 1 FROM solution_votes WHERE comment_id=$1 AND user_id=$2`, [id, user_id]);
        if (rows.length) return res.json({ success: false, error: 'כבר הצבעת' });
        await pool.query(`INSERT INTO solution_votes(comment_id,user_id) VALUES($1,$2)`, [id, user_id]);
        await pool.query(`UPDATE content_comments SET solution_upvotes=solution_upvotes+1 WHERE id=$1`, [id]);
        const { rows: r } = await pool.query(`SELECT solution_upvotes FROM content_comments WHERE id=$1`, [id]);
        res.json({ success: true, solution_upvotes: r[0]?.solution_upvotes || 0 });
    } catch(e) { res.json({ success: false, error: e.message }); }
});

// POST /api/kol-haam/content/:id/toggle-comments — SA only
app.post('/api/kol-haam/content/:id/toggle-comments', verifySA, async (req, res) => {
    const { id } = req.params;
    try {
        const { rows } = await pool.query(`SELECT comments_enabled FROM content_items WHERE id=$1`, [id]);
        if (!rows.length) return res.json({ success: false, error: 'לא נמצא' });
        const newVal = !rows[0].comments_enabled;
        await pool.query(`UPDATE content_items SET comments_enabled=$1 WHERE id=$2`, [newVal, id]);
        res.json({ success: true, comments_enabled: newVal });
    } catch(e) { res.json({ success: false, error: e.message }); }
});

// POST /api/sa/kol-haam/seed-sample — SA only, inserts sample article + comments
app.post('/api/sa/kol-haam/seed-sample', verifySA, async (req, res) => {
    const client = await pool.connect();
    try {
        await client.query('BEGIN');

        // בדיקה שכבר לא קיים דוגמה כזו
        const existing = await client.query(`SELECT id FROM content_items WHERE title LIKE '[דוגמה]%' AND is_sample_data=TRUE LIMIT 1`);
        if (existing.rows.length) {
            await client.query('ROLLBACK');
            return res.json({ success: false, error: 'דוגמה כבר קיימת (id=' + existing.rows[0].id + ')' });
        }

        // מציאת קהילה ופרופיל כותב לדוגמה
        const { rows: communities } = await client.query(`SELECT id FROM communities LIMIT 1`);
        if (!communities.length) { await client.query('ROLLBACK'); return res.json({ success: false, error: 'אין קהילות במערכת' }); }
        const communityId = communities[0].id;

        let { rows: profiles } = await client.query(`SELECT ap.id FROM author_profiles ap LIMIT 1`);
        if (!profiles.length) {
            // מציאת family_group לשימוש בפרופיל הדוגמה
            const { rows: fgs } = await client.query(`SELECT id FROM family_groups LIMIT 1`);
            if (!fgs.length) { await client.query('ROLLBACK'); return res.json({ success: false, error: 'אין משתמשים במערכת — יש להירשם תחילה' }); }
            const { rows: inserted } = await client.query(`
                INSERT INTO author_profiles (family_group_id, home_community_id)
                VALUES ($1, $2)
                ON CONFLICT (family_group_id) DO UPDATE SET home_community_id=EXCLUDED.home_community_id
                RETURNING id`, [fgs[0].id, communityId]);
            profiles = inserted;
        }
        const authorProfileId = profiles[0].id;

        let { rows: cats } = await client.query(`SELECT id FROM content_categories LIMIT 1`);
        if (!cats.length) {
            const { rows: newCat } = await client.query(`
                INSERT INTO content_categories (title, scope_level, community_id)
                VALUES ('משפחה וחינוך', 'GLOBAL', NULL) RETURNING id`);
            cats = newCat;
        }
        const categoryId = cats[0].id;

        const tldrJson = JSON.stringify([
            'שבע משפחות מרמת־אלה חילקו ביניהן את 38 ימי החופש הגדול בתורנות יומית.',
            'כל הורה לקח 5–6 ימים בלבד, וקיבל בתמורה 32 ימים מכוסים.',
            'העלות לילד ירדה מכ־5,100 ₪ בקייטנות לכ־800 ₪ — חומרים וכניסות בלבד.',
            'הכלי היחיד: גיליון משותף עם עמודה לכל יום ושורה לכל ילד.',
            'שלוש קבוצות נוספות בשכונה אימצו את המודל כבר הקיץ.'
        ]);

        const contentHtml = `
<p>במרץ האחרון, בקבוצת הוואטסאפ של כיתה ג׳2, מישהי כתבה משפט שכולם חשבו ואף אחד לא אמר: ״אני לא יכולה לעשות עוד קיץ כזה.״ תוך שעתיים היו שם 60 הודעות. תוך שבועיים ישבו שבעה הורים במרפסת עם גיליון ריק פתוח על מסך של לפטופ.</p>
<p>מה שיצא משם לא היה עמותה, לא חוג ולא קייטנה. זו הייתה טבלה. אבל הטבלה הזו כיסתה 38 ימי חופש עבור תשעה ילדים בגילי 6 עד 11, והורידה את ההוצאה המשפחתית הממוצעת בקרוב ל־85 אחוז.</p>
<h3>הבעיה: 38 ימים ושני הורים עובדים</h3>
<p>שנת הלימודים נגמרת ב־20 ביוני. הצהרון נסגר יומיים לפני. הקייטנה העירונית מכסה שלושה שבועות, בשעות 8:00–13:00, ועולה כ־1,400 ₪ לילד. נשארים כשלושה שבועות פתוחים באוגוסט, בדיוק כשמאגר ימי החופשה של רוב ההורים כבר ריק.</p>
<p>״עשינו את החשבון על הנייר בפעם הראשונה,״ מספרת רונית לוי, אחת משבע האמהות בקבוצה. ״שלושה ילדים, קייטנה פרטית באוגוסט, פלוס מטפלת לשעתיים בסוף היום. הגענו ל־15 אלף שקל. פשוט הפסקנו לספור.״</p>
<figure>
  <img src="/kol-haam-assets/images/content/inner-1-fridge-schedule.png" alt="לוח הקיץ המודפס על המקרר" onerror="this.parentElement.style.display='none'">
  <figcaption>לוח הקיץ המודפס, גרסה 4. כל צבע הוא הורה תורן. צילום: דנה פרץ</figcaption>
</figure>
<h3>איך בנו את הלוח</h3>
<p>הכלל היחיד שנקבע בפגישה הראשונה: הורה תורן אחד ליום, אחראי מ־8:30 עד 15:00, לכל הילדים שנרשמו לאותו יום. לא חובה לקחת את כולם — מי שמסוגל לחמישה ילדים לוקח חמישה, מי שיכול לשלושה מסמן שלושה.</p>
<p>כל הורה בחר מראש את הימים שנוח לו: יום עבודה מהבית, יום שישי קצר, או יום שממילא לקח חופש. אחרי סבב אחד של בחירות נשארו תשעה ימים יתומים. אותם חילקו בהגרלה, וזה לקח שבע דקות.</p>
<p>התוכן של כל יום נקבע לפי מה שלהורה התורן ממילא נוח: יום מים בגינה, יום אפייה, יום ספרייה עירונית, יום סרט בסלון עם מזגן. שלושה ימים בקיץ כולם יצאו יחד לטיול משותף במימון קופה קטנה של 150 ₪ למשפחה.</p>
<blockquote>״הטעות שלנו בהתחלה הייתה לנסות לתכנן פעילות מושקעת לכל יום. אחרי שבוע הבנו שהילדים מבסוטים הכי הרבה מיום שבו לא קורה כלום.״<br><cite>— רונית לוי, מארגנת הקבוצה</cite></blockquote>
<h3>מה השתבש</h3>
<p>שני דברים. הראשון: בשבוע השלישי אחד הילדים חלה, וההורה התורן גילה בשמונה בבוקר שהוא מארח חמישה ילדים בזמן שהוא בעצמו לא ישן. מאז נוסף כלל ״הורה גיבוי״ — שם שני לכל יום, שמתבקש רק במקרה חירום.</p>
<p>השני: אחת המשפחות פרשה באמצע יולי בגלל נסיעה לחו״ל שלא דווחה מראש, ופתאום היו שני ימים בלי אחראי. הפתרון היה פשוט ולא נעים — לוח הזמנים ננעל ב־1 ביוני, ושינוי אחרי התאריך הזה מחייב למצוא מחליף בעצמך.</p>
<p>״זה לא היה חלק,״ אומרת לוי. ״אבל אף אחד לא הפסיק לדבר עם אף אחד, וזה בעצם המדד היחיד שחשוב לנו.״</p>
<figure>
  <img src="/kol-haam-assets/images/content/inner-2-water-day.png" alt="יום מים בחצר המשותפת" onerror="this.parentElement.style.display='none'">
  <figcaption>יום מים בחצר המשותפת, 14 ביולי. תשעה ילדים, הורה תורן אחד. צילום: דנה פרץ</figcaption>
</figure>
<h3>הכסף: מה זה באמת חסך</h3>
<p>העלות הישירה של הקיץ למשפחה עמדה על כ־800 ₪ לילד: 350 ₪ קופה משותפת לחומרים, 300 ₪ לשלושת הטיולים, ועוד כ־150 ₪ ארוחות. מול זה, החלופה שתומחרה במרץ — קייטנה עירונית ואחריה קייטנה פרטית — עמדה על כ־5,100 ₪ לילד.</p>
<p>אבל המספר שההורים מזכירים ראשון הוא אחר: ימי חופשה. במקום שני הורים שמפצלים 15 ימי חופשה כל אחד, כל הורה ניצל בממוצע 5.5 ימים. השאר נשמרו לחגי תשרי.</p>
<h3>מה צריך כדי להתחיל אצלכם</h3>
<p>לפי הקבוצה, שלושה תנאים: בין חמש לשמונה משפחות (פחות מזה נופל על אדם אחד, יותר מזה הופך לניהול), ילדים בטווח גילים של עד ארבע שנים, ומרחק הליכה סביר בין הבתים. אחרי זה נשאר רק להחליט על התאריך שבו הלוח ננעל.</p>
<p>התבנית של הגיליון פתוחה לכל חברי הקהילה, והקבוצה מציעה שיחת ייעוץ של חצי שעה למי שרוצה להקים קבוצה דומה לקראת חופשת סוכות.</p>`;

        const { rows: [item] } = await client.query(`
            INSERT INTO content_items
                (title, subtitle, content_html, content_type, scope_type, status, community_id, author_profile_id, category_id,
                 cover_image_url, reading_time_minutes, quick_summary_20s, is_sample_data, published_at)
            VALUES ($1,$2,$3,'ARTICLE','LOCAL','PUBLISHED_LOCAL',$4,$5,$6,$7,4,$8,TRUE,'2026-08-15T09:00:00Z')
            RETURNING id`,
            [
                '[דוגמה] החופש הגדול נגמר בפלוס: שבע משפחות בנו לוח קיץ משותף וחסכו 4,300 ₪ לילד',
                'בלי עמותה, בלי תקציב עירוני ובלי אפליקציה בתשלום — גיליון אחד משותף, תורנות של הורה אחראי ליום, ו־38 ימי חופש שעברו בלי פאניקה של יום ראשון בבוקר',
                contentHtml,
                communityId, authorProfileId, categoryId,
                '/kol-haam-assets/images/covers/hero-summer-calendar.png',
                tldrJson
            ]
        );
        const itemId = item.id;

        // מציאת user_id לתגובות
        const { rows: users } = await client.query(`SELECT id FROM users LIMIT 1`);
        if (!users.length) { await client.query('ROLLBACK'); return res.json({ success: false, error: 'אין משתמשים במערכת' }); }
        const userId = users[0].id;

        // 4 תגובות ראשיות (מסעיף 10 בחבילת התוכן)
        const commentRows = await Promise.all([
            client.query(`INSERT INTO content_comments (content_item_id,author_user_id,content_text,likes_count) VALUES ($1,$2,$3,47) RETURNING id`,
                [itemId, userId, 'ניסינו משהו דומה לפני שנתיים וזה קרס בשבוע השני, בדיוק בגלל מה שכתוב כאן — אף אחד לא הגדיר מי הגיבוי. הכלל של השם השני לכל יום הוא הדבר שחסר לנו. שומרת את הכתבה לפני סוכות.']),
            client.query(`INSERT INTO content_comments (content_item_id,author_user_id,content_text,likes_count) VALUES ($1,$2,$3,63) RETURNING id`,
                [itemId, userId, 'המספר שתפס אותי הוא לא 4,300 ₪ אלא 5.5 ימי חופשה במקום 15. בשביל הורה עצמאי זה ההבדל בין קיץ לבין חודש בלי הכנסה.']),
            client.query(`INSERT INTO content_comments (content_item_id,author_user_id,content_text,likes_count) VALUES ($1,$2,$3,28) RETURNING id`,
                [itemId, userId, 'שאלה פרקטית: מה עם ביטוח? אם ילד נופל בחצר של הורה אחר, מי אחראי? זה הדבר היחיד שעוצר אותנו אצלנו בשכונה.']),
            client.query(`INSERT INTO content_comments (content_item_id,author_user_id,content_text,likes_count) VALUES ($1,$2,$3,12) RETURNING id`,
                [itemId, userId, 'אצלנו זה לא יעבוד — טווח הגילים בשכונה הוא מגיל 4 עד 13. ילד בן 12 לא הולך להסכים ליום מים בגינה עם בני שש.']),
        ]);
        const [c1, c2, c3, c4] = commentRows.map(r => r.rows[0].id);

        // 7 תגובות-בנות (מסעיף 10 בחבילת התוכן)
        await Promise.all([
            client.query(`INSERT INTO content_comments (content_item_id,author_user_id,content_text,parent_comment_id,likes_count,depth_level) VALUES ($1,$2,$3,$4,0,1) RETURNING id`,
                [itemId, userId, 'דנה, בקבוצה בפועל הגיבוי הופעל רק שלוש פעמים בכל הקיץ. עצם זה שיש שם כתוב מוריד את החרדה גם כשלא משתמשים בו.', c1]),
            client.query(`INSERT INTO content_comments (content_item_id,author_user_id,content_text,parent_comment_id,likes_count,depth_level) VALUES ($1,$2,$3,$4,0,1) RETURNING id`,
                [itemId, userId, 'ואם אפשר להוסיף — הגיבוי צריך להיות הורה שממילא עובד מהבית באותו יום, אחרת זה לא באמת גיבוי.', c1]),
            client.query(`INSERT INTO content_comments (content_item_id,author_user_id,content_text,parent_comment_id,likes_count,depth_level) VALUES ($1,$2,$3,$4,0,1) RETURNING id`,
                [itemId, userId, 'בדיוק. אני עצמאית ולקחתי שני ימי תורנות בשישי — יום שממילא אני לא עובדת בו. יצא שלא הפסדתי שקל.', c2]),
            client.query(`INSERT INTO content_comments (content_item_id,author_user_id,content_text,parent_comment_id,likes_count,depth_level) VALUES ($1,$2,$3,$4,0,1) RETURNING id`,
                [itemId, userId, 'ברוב פוליסות ביטוח הדירה יש כיסוי צד ג׳ שחל גם על אורחים בבית. שווה לוודא מול הסוכן לפני הקיץ, זו שיחה של חמש דקות.', c3]),
            client.query(`INSERT INTO content_comments (content_item_id,author_user_id,content_text,parent_comment_id,likes_count,depth_level) VALUES ($1,$2,$3,$4,0,1) RETURNING id`,
                [itemId, userId, 'הוספנו לפרק הבא בסדרה סעיף שלם על זה, כולל נוסח הודעה קצר שההורים החתימו אחד את השני. לא מסמך משפטי — אבל מסדר ציפיות.', c3]),
            client.query(`INSERT INTO content_comments (content_item_id,author_user_id,content_text,parent_comment_id,likes_count,depth_level) VALUES ($1,$2,$3,$4,0,1) RETURNING id`,
                [itemId, userId, 'פיצלנו בדיוק בגלל זה. יש קבוצה שנייה בשכונה של גילי 11–14, והתורנות שם היא בעיקר ליווי לבריכה ולמתנ״ס, לא אירוח בבית.', c4]),
            client.query(`INSERT INTO content_comments (content_item_id,author_user_id,content_text,parent_comment_id,likes_count,depth_level) VALUES ($1,$2,$3,$4,0,1) RETURNING id`,
                [itemId, userId, 'רעיון מעולה לפצל לפי גיל. אצלנו זה בדיוק הבעיה — אבל מעולם לא חשבנו על שתי קבוצות מקבילות.', c4]),
        ]);

        await client.query('COMMIT');
        res.json({ success: true, content_item_id: itemId, message: 'נתוני דוגמה נוצרו בהצלחה' });
    } catch(e) {
        await client.query('ROLLBACK');
        res.status(500).json({ success: false, error: e.message });
    } finally {
        client.release();
    }
});

// POST /api/kol-haam/report
app.post('/api/kol-haam/report', verifyFamily, async (req, res) => {
    // const { user_id } = req.body; // ← ישן — rollback: החזר שורה זו
    const user_id = req.familyAuth.userId;
    const { content_item_id, comment_id, reason, notes } = req.body;
    if (!user_id || !reason) return res.json({ success: false, error: 'שדות חסרים' });
    if (!content_item_id && !comment_id) return res.json({ success: false, error: 'נדרש content_item_id או comment_id' });
    try {
        await pool.query(
            `INSERT INTO content_reports(content_item_id,comment_id,reported_by_user_id,reason,notes) VALUES($1,$2,$3,$4,$5)`,
            [content_item_id || null, comment_id || null, user_id, reason, notes || null]
        );
        if (content_item_id) {
            const { rows } = await pool.query(`UPDATE content_items SET report_count=report_count+1 WHERE id=$1 RETURNING report_count`, [content_item_id]);
            if (rows[0]?.report_count >= 5) {
                await pool.query(`UPDATE content_items SET is_quarantined=true, quarantined_at=NOW() WHERE id=$1 AND is_quarantined=false`, [content_item_id]);
            }
        }
        if (comment_id) {
            const { rows } = await pool.query(`UPDATE content_comments SET report_count=report_count+1 WHERE id=$1 RETURNING report_count`, [comment_id]);
            if (rows[0]?.report_count >= 5) {
                await pool.query(`UPDATE content_comments SET is_hidden=true WHERE id=$1`, [comment_id]);
            }
        }
        res.json({ success: true });
    } catch(e) { res.json({ success: false, error: e.message }); }
});

// GET /api/kol-haam/zm/reports — ZM sees only their communities' reports
app.get('/api/kol-haam/zm/reports', verifyZoneManager, async (req, res) => {
    const { zmSession } = req;
    try {
        const { rows: zones } = await pool.query(`SELECT zone_id FROM manager_zones WHERE manager_id=$1`, [zmSession.managerId]);
        const zoneIds = zones.map(z=>z.zone_id);
        if (!zoneIds.length) return res.json({ success: true, reports: [] });
        const { rows } = await pool.query(`
            SELECT cr.*, ci.title AS item_title, ci.community_id AS item_community_id,
                   cc.content_text AS comment_text,
                   u.name AS reporter_name
            FROM content_reports cr
            LEFT JOIN content_items ci ON ci.id = cr.content_item_id
            LEFT JOIN content_comments cc ON cc.id = cr.comment_id
            JOIN users u ON u.id = cr.reported_by_user_id
            WHERE cr.status='PENDING'
              AND (
                ci.community_id IN (SELECT id FROM communities WHERE zone_id=ANY($1))
                OR (cr.comment_id IS NOT NULL AND cc.content_item_id IN (SELECT id FROM content_items WHERE community_id IN (SELECT id FROM communities WHERE zone_id=ANY($1))))
              )
            ORDER BY cr.created_at DESC
        `, [zoneIds]);
        res.json({ success: true, reports: rows });
    } catch(e) { res.json({ success: false, error: e.message }); }
});

