// POST /api/menu-sections/:sectionId/items
app.post('/api/menu-sections/:sectionId/items', verifyBizOrLegacy, async (req, res) => {
    const bizGroupId = req.bizAuth.groupId;
    if (!bizGroupId) return res.status(401).json({ error: 'נדרש token' });

    try {
        const own = await pool.query(
            `SELECT mt.group_id FROM menu_sections ms
             JOIN menu_templates mt ON mt.id=ms.template_id
             WHERE ms.id=$1 AND mt.group_id=$2 AND mt.template_type='menu'`,
            [req.params.sectionId, bizGroupId]
        );
        if (!own.rows.length) return res.status(404).json({ error: 'סקשן לא נמצא' });

        const catalogId = req.body.catalog_item_id ? parseInt(req.body.catalog_item_id) : null;
        if (catalogId) {
            const catCheck = await pool.query(
                'SELECT id FROM store_catalog WHERE id=$1 AND group_id=$2',
                [catalogId, bizGroupId]
            );
            if (!catCheck.rows.length) return res.status(400).json({ error: 'מוצר קטלוג לא נמצא או לא שייך לעסק זה' });
        }

        const name = (req.body.name || '').trim();
        if (!catalogId && !name) return res.status(400).json({ error: 'שם הפריט נדרש כשאין catalog_item_id' });

        let sortOrder = req.body.sort_order !== undefined ? parseInt(req.body.sort_order) : null;
        if (sortOrder === null || isNaN(sortOrder)) {
            const maxSort = await pool.query(
                `SELECT COALESCE(MAX(sort_order),0)+1 AS next FROM menu_items WHERE section_id=$1`,
                [req.params.sectionId]
            );
            sortOrder = maxSort.rows[0].next;
        }

        const customPrice = req.body.custom_price !== undefined ? parseFloat(req.body.custom_price) : null;
        if (customPrice !== null && (isNaN(customPrice) || customPrice < 0))
            return res.status(400).json({ error: 'custom_price חייב להיות מספר אי-שלילי' });

        const r = await pool.query(`
            INSERT INTO menu_items (section_id, name, description, catalog_item_id, custom_price, image_url, allergens, is_available, sort_order)
            VALUES ($1,$2,$3,$4,$5,$6,$7,$8,$9) RETURNING *
        `, [
            req.params.sectionId,
            name || null,
            req.body.description || null,
            catalogId,
            customPrice,
            req.body.image_url || null,
            req.body.allergens || null,
            req.body.is_available !== undefined ? req.body.is_available : true,
            sortOrder
        ]);
        res.status(201).json(r.rows[0]);
    } catch(e) {
        console.error('POST /items:', e.message);
        res.status(500).json({ error: 'שגיאת שרת' });
    }
});

// PUT /api/menu-items/:id
app.put('/api/menu-items/:id', verifyBizOrLegacy, async (req, res) => {
    const bizGroupId = req.bizAuth.groupId;
    if (!bizGroupId) return res.status(401).json({ error: 'נדרש token' });

    try {
        const own = await pool.query(
            `SELECT mi.id FROM menu_items mi
             JOIN menu_sections ms ON ms.id=mi.section_id
             JOIN menu_templates mt ON mt.id=ms.template_id
             WHERE mi.id=$1 AND mt.group_id=$2 AND mt.template_type='menu'`,
            [req.params.id, bizGroupId]
        );
        if (!own.rows.length) return res.status(404).json({ error: 'פריט לא נמצא' });

        if (req.body.catalog_item_id !== undefined && req.body.catalog_item_id !== null) {
            const catCheck = await pool.query(
                'SELECT id FROM store_catalog WHERE id=$1 AND group_id=$2',
                [parseInt(req.body.catalog_item_id), bizGroupId]
            );
            if (!catCheck.rows.length) return res.status(400).json({ error: 'מוצר קטלוג לא נמצא או לא שייך לעסק זה' });
        }

        const allowed = ['name','description','catalog_item_id','custom_price','image_url','allergens','is_available','sort_order'];
        const sets = [], vals = [];
        for (const f of allowed) {
            if (req.body[f] !== undefined) { vals.push(req.body[f]); sets.push(`${f}=$${vals.length}`); }
        }
        if (!sets.length) return res.status(400).json({ error: 'לא נשלחו שדות לעדכון' });

        vals.push(req.params.id);
        const r = await pool.query(
            `UPDATE menu_items SET ${sets.join(',')} WHERE id=$${vals.length} RETURNING *`, vals
        );
        res.json(r.rows[0]);
    } catch(e) {
        console.error('PUT /items/:id:', e.message);
        res.status(500).json({ error: 'שגיאת שרת' });
    }
});

// DELETE /api/menu-items/:id
app.delete('/api/menu-items/:id', verifyBizOrLegacy, async (req, res) => {
    const bizGroupId = req.bizAuth.groupId;
    if (!bizGroupId) return res.status(401).json({ error: 'נדרש token' });

    try {
        const own = await pool.query(
            `SELECT mi.id FROM menu_items mi
             JOIN menu_sections ms ON ms.id=mi.section_id
             JOIN menu_templates mt ON mt.id=ms.template_id
             WHERE mi.id=$1 AND mt.group_id=$2 AND mt.template_type='menu'`,
            [req.params.id, bizGroupId]
        );
        if (!own.rows.length) return res.status(404).json({ error: 'פריט לא נמצא' });

        await pool.query('DELETE FROM menu_items WHERE id=$1', [req.params.id]);
        res.json({ success: true });
    } catch(e) {
        console.error('DELETE /items/:id:', e.message);
        res.status(500).json({ error: 'שגיאת שרת' });
    }
});

// ===== END MENU SECTIONS & ITEMS API =====

// ===== MENU PUBLIC API =====

const _menuPublicRateMap = new Map();
setInterval(() => {
    const now = Date.now();
    for (const [k, v] of _menuPublicRateMap) {
        if (now - v.windowStart > 3600 * 1000) _menuPublicRateMap.delete(k);
    }
}, 3600 * 1000);

function _checkMenuPublicRate(ip) {
    const now = Date.now();
    let entry = _menuPublicRateMap.get(ip);
    if (!entry || now - entry.windowStart > 3600 * 1000) {
        entry = { count: 0, windowStart: now };
    }
    if (entry.count >= 5) {
        const secsLeft = Math.ceil((3600 * 1000 - (now - entry.windowStart)) / 1000);
        return { blocked: true, secsLeft };
    }
    entry.count++;
    _menuPublicRateMap.set(ip, entry);
    return { blocked: false };
}

function _sanitizePlainText(text) {
    if (!text || typeof text !== 'string') return null;
    return sanitizeHtml(text, { allowedTags: [], allowedAttributes: {} }).trim() || null;
}

app.get('/api/menu/public/:slug', async (req, res) => {
    try {
        const tmplRes = await pool.query(
            `SELECT id,name,description,event_type,min_guests,max_guests,
                    base_price_per_person,pricing_mode,cover_image_url,logo_url,slogan,
                    contact_phone,contact_address,group_id,
                    event_mode,hide_prices,event_greeting,event_intro,event_image_url
             FROM menu_templates
             WHERE public_slug=$1 AND is_active=true AND is_public=true AND template_type='menu'`,
            [req.params.slug]
        );
        if (!tmplRes.rows.length) return res.status(404).json({ error: 'תבנית לא נמצאה' });

        const tmpl = tmplRes.rows[0];

        // extra fields — resilient to missing columns/rows
        let showRelated = false, storeId = null, pricingMode = 'per_person';
        try {
            const extRes = await pool.query(
                `SELECT mt.show_related_options, mt.pricing_mode,
                        COALESCE(ss.store_alias, fg.group_code) AS store_id
                 FROM menu_templates mt
                 JOIN family_groups fg ON fg.id = mt.group_id
                 LEFT JOIN store_settings ss ON ss.group_id = mt.group_id
                 WHERE mt.id=$1`, [tmpl.id]
            );
            if (extRes.rows.length) {
                showRelated = !!extRes.rows[0].show_related_options;
                storeId = extRes.rows[0].store_id || null;
                pricingMode = extRes.rows[0].pricing_mode || 'per_person';
            }
        } catch(extErr) { /* columns may not exist yet — graceful skip */ }
        const sectionsRes = await pool.query(`
            SELECT ms.*,
                   COALESCE(json_agg(mi.* ORDER BY mi.sort_order) FILTER (WHERE mi.id IS NOT NULL), '[]') AS items
            FROM menu_sections ms
            LEFT JOIN menu_items mi ON mi.section_id = ms.id
            WHERE ms.template_id=$1
            GROUP BY ms.id
            ORDER BY ms.sort_order
        `, [tmpl.id]);

        // reference חי מ-store_catalog לכל item עם catalog_item_id
        const catalogIds = [];
        sectionsRes.rows.forEach(s => s.items.forEach(i => { if (i.catalog_item_id) catalogIds.push(i.catalog_item_id); }));
        let catMap = {};
        if (catalogIds.length) {
            const catRes = await pool.query(
                'SELECT id,name,price,image_url FROM store_catalog WHERE id=ANY($1)', [catalogIds]
            );
            catRes.rows.forEach(r => { catMap[r.id] = r; });
        }

        const sections = sectionsRes.rows.map(s => ({
            id: s.id, name: s.name, description: s.description,
            min_choices: s.min_choices, max_choices: s.max_choices,
            is_required: s.is_required, sort_order: s.sort_order,
            price_modifier: s.price_modifier,
            items: s.items.map(i => ({
                id: i.id, name: i.catalog_item_id && catMap[i.catalog_item_id] ? catMap[i.catalog_item_id].name : i.name,
                description: i.description,
                price: i.custom_price != null ? i.custom_price : (catMap[i.catalog_item_id]?.price ?? null),
                image_url: i.image_url || catMap[i.catalog_item_id]?.image_url || null,
                allergens: i.allergens,
                is_available: i.is_available, sort_order: i.sort_order,
                catalog_item_id: i.catalog_item_id
            }))
        }));

        const { group_id, ...tmplPublic } = tmpl;
        res.json({ ...tmplPublic, pricing_mode: pricingMode, show_related_options: showRelated, store_id: storeId, sections });
    } catch(e) {
        console.error('GET /api/menu/public/:slug:', e.message);
        res.status(500).json({ error: 'שגיאת שרת' });
    }
});

app.post('/api/menu/public/:slug/request', async (req, res) => {
    const clientIP = (req.headers['x-forwarded-for'] || req.socket.remoteAddress || 'unknown').split(',')[0].trim();
    const rateCheck = _checkMenuPublicRate(clientIP);
    if (rateCheck.blocked) return res.status(429).json({ error: `יותר מדי בקשות. נסה שנית בעוד ${rateCheck.secsLeft} שניות.` });

    try {
        const tmplRes = await pool.query(
            `SELECT id,group_id,min_guests,max_guests,name,notification_email FROM menu_templates
             WHERE public_slug=$1 AND is_active=true AND is_public=true AND template_type='menu'`,
            [req.params.slug]
        );
        if (!tmplRes.rows.length) return res.status(404).json({ error: 'תבנית לא נמצאה' });
        const tmpl = tmplRes.rows[0];

        // ולידציה בסיסית
        const customerName = _sanitizePlainText(req.body.customer_name);
        if (!customerName) return res.status(400).json({ error: 'שם הלקוח נדרש' });

        const customerPhone = (req.body.customer_phone || '').trim();
        if (!customerPhone || customerPhone.length < 7 || customerPhone.length > 15 || !/^[0-9+\-() ]+$/.test(customerPhone))
            return res.status(400).json({ error: 'מספר טלפון לא תקין' });

        if (req.body.event_date) {
            const todayIL = new Date().toLocaleDateString('en-CA', { timeZone: 'Asia/Jerusalem' });
            const inputDate = new Date(req.body.event_date).toISOString().slice(0, 10);
            if (inputDate < todayIL) return res.status(400).json({ error: 'תאריך האירוע לא יכול להיות בעבר' });
        }

        if (req.body.guest_count !== undefined) {
            const gc = parseInt(req.body.guest_count);
            if (isNaN(gc) || gc < 1) return res.status(400).json({ error: 'מספר אורחים לא תקין' });
            if (tmpl.min_guests && gc < tmpl.min_guests) return res.status(400).json({ error: `מינימום אורחים: ${tmpl.min_guests}` });
            if (tmpl.max_guests && gc > tmpl.max_guests) return res.status(400).json({ error: `מקסימום אורחים: ${tmpl.max_guests}` });
        }

        // ולידציית selections
        const selections = req.body.selections || {};
        if (typeof selections !== 'object' || Array.isArray(selections))
            return res.status(400).json({ error: 'selections לא תקין' });

        const sectionsRes = await pool.query(
            `SELECT id,min_choices,max_choices,is_required,name FROM menu_sections WHERE template_id=$1`,
            [tmpl.id]
        );
        const sectionMap = {};
        sectionsRes.rows.forEach(s => { sectionMap[s.id] = s; });

        for (const [secIdStr, itemIds] of Object.entries(selections)) {
            const secId = parseInt(secIdStr);
            if (!sectionMap[secId]) return res.status(400).json({ error: `section_id ${secId} לא שייך לתבנית זו` });
            if (!Array.isArray(itemIds)) return res.status(400).json({ error: `selections[${secId}] חייב להיות מערך` });
            const sec = sectionMap[secId];
            if (itemIds.length < sec.min_choices) return res.status(400).json({ error: `${sec.name}: נדרשות לפחות ${sec.min_choices} בחירות` });
            if (itemIds.length > sec.max_choices) return res.status(400).json({ error: `${sec.name}: מותרות לכל היותר ${sec.max_choices} בחירות` });
            if (itemIds.length > 0) {
                const validItems = await pool.query(
                    'SELECT id FROM menu_items WHERE id=ANY($1) AND section_id=$2',
                    [itemIds.map(Number), secId]
                );
                if (validItems.rows.length !== itemIds.length)
                    return res.status(400).json({ error: `items לא תקינים ב-section ${sec.name}` });
            }
        }
        // בדיקת sections חובה שלא נשלחו
        for (const sec of sectionsRes.rows) {
            if (sec.is_required && !selections[sec.id]) {
                const chosen = (selections[sec.id] || []).length;
                if (chosen < sec.min_choices) return res.status(400).json({ error: `${sec.name}: בחירה זו חובה` });
            }
        }

        // המרת selections מ-IDs לשמות קריאים לאחסון
        const allItemIds = Object.values(selections).flat().map(Number).filter(Boolean);
        const itemNamesRes = allItemIds.length
            ? await pool.query('SELECT id, name FROM menu_items WHERE id=ANY($1)', [allItemIds])
            : { rows: [] };
        const itemNameMap = {};
        itemNamesRes.rows.forEach(it => { itemNameMap[it.id] = it.name; });
        const selectionsNamed = {};
        for (const [secIdStr, itemIds] of Object.entries(selections)) {
            const secId = parseInt(secIdStr);
            const secName = sectionMap[secId]?.name || secIdStr;
            selectionsNamed[secName] = itemIds.map(id => itemNameMap[id] || String(id));
        }

        const customNotes = _sanitizePlainText(req.body.custom_notes);
        const r = await pool.query(`
            INSERT INTO menu_quote_requests
              (template_id, group_id, customer_name, customer_phone, customer_email,
               event_date, guest_count, selections, custom_notes, source, status)
            VALUES ($1,$2,$3,$4,$5,$6,$7,$8,$9,'public_form','pending')
            RETURNING id
        `, [
            tmpl.id, tmpl.group_id,
            customerName, customerPhone,
            _sanitizePlainText(req.body.customer_email),
            req.body.event_date || null,
            req.body.guest_count ? parseInt(req.body.guest_count) : null,
            JSON.stringify(selectionsNamed),
            customNotes
        ]);

        const reqNumber = 'HG-' + String(r.rows[0].id).padStart(4, '0');

        // שליחת מייל לעסק אם הוגדר notification_email
        if (tmpl.notification_email) {
            const eventLabels = { wedding:'חתונה', bar_mitzvah:'בר/בת מצווה', birthday:'יום הולדת', corporate:'אירוע עסקי', other:'אירוע' };
            const selLines = Object.entries(selections).map(([secId, ids]) => {
                const sec = sectionMap[secId];
                return sec ? `<tr><td style="padding:4px 10px;color:#6b7280;font-size:13px">${sec.name}</td><td style="padding:4px 10px;font-size:13px">${ids.length} בחירות</td></tr>` : '';
            }).join('');
            const emailHtml = `
<div dir="rtl" style="font-family:Arial,sans-serif;max-width:560px;margin:auto;color:#1e293b">
  <div style="background:#241E19;padding:24px 28px;border-radius:8px 8px 0 0">
    <h2 style="margin:0;color:#FBF7EF;font-size:19px">פנייה חדשה — ${tmpl.name}</h2>
    <div style="color:#9C8C71;font-size:13px;margin-top:4px">מספר פנייה: <strong style="color:#E7DFD0">${reqNumber}</strong></div>
  </div>
  <div style="background:#FBF7EF;padding:24px 28px;border:1px solid #E5DCCB;border-top:none;border-radius:0 0 8px 8px">
    <table style="width:100%;border-collapse:collapse;margin-bottom:16px">
      <tr><td style="padding:4px 10px;color:#6b7280;font-size:13px">שם</td><td style="padding:4px 10px;font-size:13px;font-weight:600">${customerName}</td></tr>
      <tr style="background:#f8f4ee"><td style="padding:4px 10px;color:#6b7280;font-size:13px">טלפון</td><td style="padding:4px 10px;font-size:13px">${customerPhone}</td></tr>
      ${req.body.customer_email ? `<tr><td style="padding:4px 10px;color:#6b7280;font-size:13px">אימייל</td><td style="padding:4px 10px;font-size:13px">${req.body.customer_email}</td></tr>` : ''}
      ${req.body.event_date ? `<tr style="background:#f8f4ee"><td style="padding:4px 10px;color:#6b7280;font-size:13px">תאריך אירוע</td><td style="padding:4px 10px;font-size:13px">${req.body.event_date}</td></tr>` : ''}
      ${req.body.guest_count ? `<tr><td style="padding:4px 10px;color:#6b7280;font-size:13px">מספר אורחים</td><td style="padding:4px 10px;font-size:13px">${req.body.guest_count}</td></tr>` : ''}
      ${selLines}
      ${customNotes ? `<tr style="background:#f8f4ee"><td style="padding:4px 10px;color:#6b7280;font-size:13px">הערות</td><td style="padding:4px 10px;font-size:13px">${customNotes}</td></tr>` : ''}
    </table>
    <div style="font-size:11px;color:#9C8C71;border-top:1px solid #E5DCCB;padding-top:12px">OneFlow Life · מערכת ניהול אירועים</div>
  </div>
</div>`;
            sendSystemEmail(tmpl.notification_email, `פנייה חדשה לתפריט: ${tmpl.name} — ${customerName}`, emailHtml).catch(() => {});
        }

        res.status(201).json({ success: true, request_number: reqNumber });
    } catch(e) {
        console.error('POST /api/menu/public/:slug/request:', e.message);
        res.status(500).json({ error: 'שגיאת שרת' });
    }
});

