// ── verifyBizOrLegacy middleware ───────────────────────────────
// אם יש טוקן תקין — groupId מה-session; אחרת — fallback ל-groupId מה-body (legacy).
// לא מחובר לאף endpoint עדיין.
async function verifyBizOrLegacy(req, res, next) {
    const authHeader = req.headers.authorization || '';
    const rawToken = authHeader.startsWith('Bearer ') ? authHeader.slice(7) : authHeader;

    if (rawToken) {
        const tokenHash = _hashToken(rawToken);
        try {
            const r = await pool.query(
                `SELECT group_id, user_id, expires_at, session_type FROM family_sessions WHERE token_hash=$1`,
                [tokenHash]
            );
            const row = r.rows[0];
            if (row && new Date(row.expires_at) >= new Date()) {
                if (row.session_type !== 'biz') {
                    return res.status(403).json({ error: 'נדרש token מסוג עסקי' });
                }
                pool.query(`UPDATE family_sessions SET last_seen=NOW() WHERE token_hash=$1`, [tokenHash]).catch(() => {});
                req.bizAuth = { groupId: row.group_id, userId: row.user_id, fromToken: true };
                return next();
            }
        } catch(e) {}
        // token קיים בheader אבל פג תוקף / לא נמצא ב-DB
        return res.status(401).json({ error: 'token לא תקף' });
    }

    // אין Authorization header — legacy fallback
    const legacyGroupId = req.body?.groupId || req.query?.groupId || null;
    console.warn(`[verifyBizOrLegacy] legacy fallback — no token, groupId=${legacyGroupId}, path=${req.path}`);
    req.bizAuth = { groupId: legacyGroupId, userId: null, fromToken: false };
    next();
}

// ── AI Copilot quota helpers ──────────────────────────────────
async function checkAICopilotQuota(groupId) {
    // קריאת מכסה מה-settings (ניתנת לעריכה מ-SA)
    let dailyLimit = 20;
    try {
        const s = await pool.query(`SELECT value FROM system_settings WHERE key='kh_ai_copilot_daily_limit'`);
        if (s.rows[0]) dailyLimit = parseInt(s.rows[0].value) || 20;
    } catch(e) {}

    // UPSERT לשורת השימוש של היום
    const r = await pool.query(`
        INSERT INTO kh_ai_copilot_usage (group_id, usage_date, call_count)
        VALUES ($1, CURRENT_DATE, 0)
        ON CONFLICT (group_id, usage_date) DO UPDATE SET call_count=kh_ai_copilot_usage.call_count
        RETURNING call_count
    `, [groupId]);

    const used = r.rows[0].call_count;
    return { allowed: used < dailyLimit, used, dailyLimit };
}

async function incrementAICopilotUsage(groupId) {
    await pool.query(`
        INSERT INTO kh_ai_copilot_usage (group_id, usage_date, call_count)
        VALUES ($1, CURRENT_DATE, 1)
        ON CONFLICT (group_id, usage_date) DO UPDATE SET call_count=kh_ai_copilot_usage.call_count+1
    `, [groupId]);
}

// ── ניקוי sessions פגות — cron יומי ──────────────────────────
setInterval(async () => {
    try {
        const r = await pool.query(`DELETE FROM family_sessions WHERE expires_at < NOW()`);
        if (r.rowCount > 0) console.log(`[family-auth] cleaned ${r.rowCount} expired sessions`);
    } catch(e) {}
}, 24 * 60 * 60 * 1000);

